function cleanData(d){d=d&&typeof d==='object'?d:{};return {schema:2,doctrineRead:Array.isArray(d.doctrineRead)?[...new Set(d.doctrineRead.filter(id=>typeof id==='string'&&(DATA.catechismCourse?.some(l=>l.id===id)||DATA.doctrineSupplements?.some(l=>'further-'+l.id===id))))]:[],lessons:Array.isArray(d.lessons)?[...new Set(d.lessons.filter(id=>typeof id==='string'&&DATA.lessons?.some(l=>l.id===id)))]:[],saved:filterSlugs(d.saved),reviewed:filterSlugs(d.reviewed),practiced:Array.isArray(d.practiced)?d.practiced.filter(x=>typeof x==='string'&&DATA.memory.some(m=>slug(m.ref)===x)):[],size:[17,18,19,20,21,22,23,24].includes(d.size)?d.size:19,theme:['light','dark','system'].includes(d.theme)?d.theme:'system',last:d.last&&validRoute(d.last.route)?{route:d.last.route,scroll:Math.max(0,Math.min(100000,Number(d.last.scroll)||0)),label:String(d.last.label||'Continue reading').slice(0,100)}:null}}
