function renderHome(){const last=prefs.last;return `<section class="home-hero"><div class="wrap hero-grid"><div><span class="eyebrow">Scripture open. Christ before us.</span><h1 class="hero-title">Read with care.<br><em>Know the Word.</em></h1><p class="hero-lead">Find your place in Scripture and learn to read it in context. Open a book guide beside your Bible.</p><form id="homeSearch" class="home-search" role="search"><label class="sr-only" for="homeQuery">Find a book or search the companion</label><input id="homeQuery" type="search" placeholder="Which book are you reading?" autocomplete="off">${icon('search')}<button class="sr-only" type="submit">Search</button></form><div class="search-suggest row small"><a href="#books/genesis">Genesis</a><span class="muted">·</span><a href="#books/psalms">Psalms</a><span class="muted">·</span><a href="#books/john">John</a><span class="muted">·</span><a href="#books/romans">Romans</a></div><p class="hero-note">All 66 books · Westminster theology · KJV passages included</p><a class="mobile-start small" href="#${last?last.route:'examples/0'}" ${last?'data-resume':''}>${last?'Continue reading '+esc(last.label):'Try a worked example'} →</a></div><aside class="opening-card"><span class="folio" aria-hidden="true">${last?'↗':'01'}</span><span class="eyebrow">${last?'Your place is kept':'A good place to begin'}</span><h2>${last?esc(last.label):'How do I read<br>this passage?'}</h2><p>${last?'Return to where you left off, or choose another book below.':'See how genre and context help us understand what God has said.'}</p><a class="button" href="#${last?last.route:'examples/0'}" ${last?'data-resume':''}>${last?'Continue reading':'Try a worked example'} →</a><div class="fine-line"></div><a href="#gospel" style="color:inherit;font-size:.83rem">Begin with the gospel ↗</a></aside></div></section><section class="section"><div class="wrap"><div class="section-top"><div><span class="eyebrow">Open a book guide</span><h2>Where are you reading?</h2></div><a class="button secondary small" href="#books">Browse by section →</a></div><div class="book-index">${DATA.books.map(bookTile).join('')}</div></div></section><section class="section tinted"><div class="wrap"><div class="section-top"><div><span class="eyebrow">A habit to learn</span><h2>From the passage to your life.</h2></div><a href="#principles">Read the principles →</a></div><div class="method-grid"><div class="method-card"><span class="num">01</span><h3>Notice the writing.</h3><p>Identify the speaker and the kind of passage. A poem and a letter don't use language in exactly the same way.</p></div><div class="method-card"><span class="num">02</span><h3>Follow the meaning.</h3><p>Read the words in their setting. Let the surrounding argument and the rest of Scripture guide you.</p></div><div class="method-card"><span class="num">03</span><h3>Respond in faith.</h3><p>Consider what the passage calls you to believe or do, in light of its fulfillment and your life in Christ.</p></div></div></div></section>`}
const bookFilters={q:'',testament:'all',group:'all'};
function matchingBooks(){const q=bookFilters.q.trim().toLowerCase();return DATA.books.filter(b=>(bookFilters.testament==='all'||b.testament===bookFilters.testament)&&(bookFilters.group==='all'||b.group===bookFilters.group)&&(!q||(b.name+' '+b.introText+' '+b.helps.map(h=>h.text).join(' ')).toLowerCase().includes(q)))}
function bookListHtml(books){return books.length?groups.filter(g=>books.some(b=>b.group===g)).map(g=>`<section class="book-group"><div class="group-label"><h2>${esc(g)}</h2><small>${books.filter(b=>b.group===g).length} books</small></div><div class="book-index">${books.filter(b=>b.group===g).map(bookTile).join('')}</div></section>`).join(''):'<div class="empty">No books match. Try another search or clear the filters.</div>'}
function renderBooks(){return pageTop('The whole Bible','Find your book.','A short overview and practical reading helps for every book of Scripture.')+`<div class="wrap"><div class="filters"><label class="field grow">Search the guides<input type="search" id="bookQuery" value="${esc(bookFilters.q)}" placeholder="A book, theme, or passage"></label><label class="field">Testament<select id="testamentFilter"><option value="all">Both Testaments</option>${['Old Testament','New Testament'].map(t=>`<option ${t===bookFilters.testament?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Section<select id="groupFilter"><option value="all">Every section</option>${groups.map(g=>`<option ${g===bookFilters.group?'selected':''}>${esc(g)}</option>`).join('')}</select></label><button class="button secondary small" data-clear-books>Clear</button></div><p class="result-count" id="bookCount" aria-live="polite">${matchingBooks().length} books</p><div id="bookList">${bookListHtml(matchingBooks())}</div></div>`}
