function readerTools(b){return `<details class="reader-tools"><summary>${icon('book')} Reading tools <span class="muted small">Text size · save · focus</span></summary><div class="tool-content"><div class="font-control" aria-label="Reading text size"><button class="icon" data-size="-1" aria-label="Decrease reading text size">A−</button><output class="size-output" aria-live="polite">${prefs.size}px</output><button class="icon" data-size="1" aria-label="Increase reading text size">A+</button></div><button class="button secondary small" data-save="${b.slug}" aria-pressed="${prefs.saved.includes(b.slug)}">${prefs.saved.includes(b.slug)?'✓ Saved':'Save guide'}</button><button class="button secondary small" data-review="${b.slug}" aria-pressed="${prefs.reviewed.includes(b.slug)}">${prefs.reviewed.includes(b.slug)?'✓ Reviewed':'Mark reviewed'}</button><button class="button secondary small" data-focus="${b.slug}">One help at a time</button><button class="button secondary small" data-bible="${esc(b.name)} 1">Read KJV</button><button class="button secondary small" data-print>Print</button></div></details>`}
function guide(b){const prev=DATA.books[b.index-2],next=DATA.books[b.index];return `<div class="wrap"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#books">Book guides</a><span>/</span><span>${esc(b.name)}</span></nav><header class="reader-head"><span class="eyebrow">${esc(b.testament)} · ${esc(b.group)}</span><h1>${esc(b.name)}</h1><div class="reader-meta"><span>${b.helps.length} reading helps</span><span>·</span><span>${Math.max(2,Math.ceil((b.introText+' '+b.helps.map(h=>h.text).join(' ')).split(/\s+/).length/180))} minute guide</span><span>·</span><span>Book ${b.index} of 66</span></div></header>${readerTools(b)}<div class="reader-layout"><aside class="reader-sidebar"><span class="sidebar-title">In this guide</span><nav aria-label="On this page"><a href="#books/${b.slug}" data-scroll="overview">Overview</a>${b.helps.map((h,i)=>`<a href="#books/${b.slug}/${i+1}" data-scroll="help-${i+1}">${String(i+1).padStart(2,'0')} &nbsp; ${esc(shortTitle(h.text))}</a>`).join('')}</nav><div class="sidebar-foot"><p>Read the passage itself before consulting a help.</p><a href="#examples">Try a worked example →</a></div></aside><article class="reader prose" data-ref-book="${esc(b.name)}"><section class="overview" id="overview"><span class="eyebrow">Before you read</span>${b.intro}</section>${b.helps.map((h,i)=>`<section class="help" id="help-${i+1}"><div class="help-top"><span class="help-label">Reading help ${String(i+1).padStart(2,'0')}</span><a class="anchor" href="#books/${b.slug}/${i+1}" aria-label="Link to reading help ${i+1}">#</a></div>${h.html}</section>`).join('')}<nav class="guide-nav" aria-label="Adjacent books">${prev?`<a class="button secondary" href="#books/${prev.slug}">← ${esc(prev.name)}</a>`:'<span></span>'}${next?`<a class="button secondary" href="#books/${next.slug}">${esc(next.name)} →</a>`:''}</nav><p class="reading-footer">Your reading place is kept on this device. <a href="#reading">Saved guides &amp; backup</a></p></article></div></div>`}
function shortTitle(t){const first=t.split(/(?<=[.!?])\s/)[0];return first.length>51?first.slice(0,48).replace(/\s+\S*$/,'')+'…':first}
const ruleFilters={q:'',group:'All'};
function rulesList(){const q=ruleFilters.q.toLowerCase().trim();const rows=DATA.rules.filter(r=>(ruleFilters.group==='All'||r.category===ruleFilters.group)&&(!q||(r.text+' '+r.category).toLowerCase().includes(q)));return rows.length?rows.map(r=>`<section class="help" id="principle-${r.number}"><div class="help-top"><span class="help-label">${String(r.number).padStart(2,'0')} · ${esc(r.category)}</span><a class="anchor" href="#principles/${r.number}" aria-label="Link to principle ${r.number}">#</a></div>${r.html}</section>`).join(''):'<p class="empty">No principles match that search.</p>'}
function renderPrinciples(){const cats=['All',...new Set(DATA.rules.map(r=>r.category))];return pageTop('Learning to read','Principles worth practicing.',`${DATA.rules.length} distinct helps for understanding Scripture and putting it into practice.`)+`<div class="wrap"><div class="filters"><label class="field grow">Find a principle<input id="ruleQuery" type="search" value="${esc(ruleFilters.q)}" placeholder="Context, covenant, symbols…"></label><label class="field">Subject<select id="ruleGroup">${cats.map(c=>`<option ${c===ruleFilters.group?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div class="reader-layout"><aside class="reader-sidebar"><span class="sidebar-title">Put it to work</span><p style="margin-top:16px">Read a principle, then try it on a particular passage.</p><a href="#examples">Open the worked examples →</a></aside><article class="reader prose" id="ruleList">${rulesList()}</article></div></div>`}
function renderExamples(n){if(n!==undefined&&DATA.examples[+n]){const e=DATA.examples[+n];return `<div class="wrap"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#examples">Worked examples</a><span>/</span><span>${+n+1} of ${DATA.examples.length}</span></nav><header class="reader-head"><span class="eyebrow">Learn with a passage open</span><h1 style="font-size:clamp(2.6rem,5vw,4rem)">${esc(e.title)}</h1><button class="button secondary small" data-bible="${esc(e.ref)}">Read ${esc(e.ref)} · KJV</button></header><div class="reader-layout"><aside class="reader-sidebar"><span class="sidebar-title">Follow the method</span><p style="margin-top:16px">Read the passage before the explanation. Check each step against the text.</p></aside><article class="reader prose"><p class="example-question">${esc(e.question)}</p>${e.steps.map(([t,p],i)=>`<section class="example-step"><small>Step ${i+1}</small><h2>${esc(t)}</h2><p>${esc(p)}</p></section>`).join('')}<div class="callout">Try it yourself. Explain the passage in your own words, then name the part of the text that supports your explanation.</div><nav class="guide-nav"><a class="button secondary" href="#examples">← All examples</a>${+n<DATA.examples.length-1?`<a class="button" href="#examples/${+n+1}">Next example →</a>`:'<a class="button" href="#books">Choose a book →</a>'}</nav></article></div></div>`}return pageTop('A passage at a time','See the method at work.','Walk through a real question with the text open beside the explanation.')+`<div class="wrap"><div class="cards">${DATA.examples.map((e,i)=>`<a class="card card-link" href="#examples/${i}"><span class="eyebrow">Example ${String(i+1).padStart(2,'0')}</span><h3>${esc(e.title)}</h3><p>${esc(e.question)}</p><span class="small">${esc(e.ref)} →</span></a>`).join('')}</div></div>`}
function renderGospel(n=0){n=Number(n);if(!Number.isInteger(n)||!DATA.gospel[n])n=0;const g=DATA.gospel[n];return pageTop('The good news','Salvation in Jesus Christ.','What God has done for sinners, how we receive Christ, and the life that follows.')+`<div class="wrap"><label class="field library-mobile">Choose a section<select id="gospelSelect">${DATA.gospel.map((g,i)=>`<option value="${i}" ${i===n?'selected':''}>${i+1}. ${esc(g.title)}</option>`).join('')}</select></label><div class="reader-layout"><aside class="reader-sidebar"><span class="sidebar-title">The gospel</span><nav aria-label="Gospel sections">${DATA.gospel.map((s,i)=>`<a href="#gospel/${i}" ${i===n?'aria-current="page" style="color:var(--green);border-color:var(--green)"':''}>${i+1}. ${esc(s.title)}</a>`).join('')}</nav></aside><article class="reader prose"><span class="eyebrow">Section ${n+1} of ${DATA.gospel.length}</span><h2 style="margin-top:0">${esc(g.title)}</h2>${g.html}<nav class="guide-nav">${n?`<a class="button secondary" href="#gospel/${n-1}">← Previous</a>`:'<span></span>'}${n<DATA.gospel.length-1?`<a class="button" href="#gospel/${n+1}">Next section →</a>`:'<a class="button" href="#books">Open a book guide →</a>'}</nav></article></div></div>`}

const libItems=[['glossary','Glossary'],['scripture-memory','Scripture memory'],['how-to-use-this-guide','Using this companion'],['recommended-reading','Further reading'],['on-memorizing-scripture','Learning a passage'],['scripture-index','Passage index'],['foreword','A word from the author'],['preface','About the guide'],['closing-word','A closing word'],['about-the-author','About the author'],['sources','Sources & revision'],['copyright','Copyright'],['dedication','Dedication']];
const libNames={'glossary':'Glossary','scripture-memory':'Scripture Memory','how-to-use-this-guide':'How to Use This Guide','recommended-reading':'Recommended Reading','on-memorizing-scripture':'On Memorizing Scripture','foreword':'Foreword','preface':'Preface','closing-word':'Closing Word','about-the-author':'About the Author','copyright':'Copyright','dedication':'Dedication'};
let glossaryQuery='', memoryCat='All';
function glossaryHtml(){const terms=DATA.glossary.filter(t=>(t.term+' '+t.text).toLowerCase().includes(glossaryQuery.toLowerCase()));return terms.length?terms.map(t=>`<details class="term" id="term-${slug(t.term)}"><summary>${esc(t.term)}</summary><div class="prose">${t.definition}${t.lesson?`<a class="lesson-link" href="#learn/${t.lesson}">Read the fuller lesson →</a>`:''}</div></details>`).join(''):'<div class="empty">No definitions match that search.</div>'}
function memoryCards(){return DATA.memory.filter(m=>memoryCat==='All'||m.category===memoryCat).map(m=>{const id=slug(m.ref),done=prefs.practiced.includes(id);return `<article class="card memory-card"><span class="tag">${esc(m.category)}</span><h3>${esc(m.ref)}</h3><p class="small muted">Try to recall the passage, then check its wording.</p><div class="memory-quote hidden" id="memory-${id}">${m.html}</div><div class="memory-actions"><button class="button small" data-reveal="${id}" aria-expanded="false" aria-controls="memory-${id}">Reveal passage</button><button class="button secondary small" data-practiced="${id}" aria-pressed="${done}">${done?'✓ Practiced':'Mark practiced'}</button><button class="button secondary small" data-bible="${esc(m.ref)}">Context</button></div></article>`}).join('')}
function sourcesHtml(){return `<p>This edition revises the writing and reading interface of <i>Bible Reading Helps</i>. It keeps all 66 book guides while merging repeated material and distinguishing confessional doctrine from disputed interpretations.</p><h3>What changed</h3><p>The general helps have been reorganized into ${DATA.rules.length} principles. The book guides contain ${DATA.books.reduce((n,b)=>n+b.helps.length,0)} helps after repeated opening instructions were removed. Six worked examples demonstrate the method. Scripture memory and passage lookup use KJV.</p><h3>Doctrinal references</h3><ul>${DATA.metadata.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></li>`).join('')}</ul><p>Read WCF 1 for Scripture and interpretation, WCF 7 to 8 for covenant and Christ's work, WCF 11 to 18 for salvation and assurance, and WCF 27 to 29 for the sacraments. WLC 49 describes Christ's suffering, and WLC 86 to 90 distinguishes the state after death from resurrection glory.</p><h3>Editorial judgment</h3><p>The guide takes the Westminster Presbyterian position on covenant and baptism. It follows the RPCNA conviction of exclusive psalmody in public worship and takes an amillennial approach in Revelation. Those positions are stated rather than treated as the unanimous conclusion of every Reformed writer.</p><h3>Bible text</h3><p>KJV passage text is included within this file so it can be read without an internet connection. Verse wording is kept separate from the explanatory prose. Where an explanation summarizes a passage, it should be read as commentary, not as an additional translation.</p>`}
function referenceIndex(){const refs=new Set();DATA.books.forEach(b=>{const a=extractRefs(b.introText+' '+b.helps.map(h=>h.text).join(' '));a.forEach(r=>refs.add(r))});DATA.rules.forEach(r=>extractRefs(r.text).forEach(x=>refs.add(x)));DATA.examples.forEach(e=>refs.add(e.ref));DATA.memory.forEach(m=>refs.add(m.ref));DATA.lessons.forEach(l=>{l.refs.forEach(r=>refs.add(r));extractRefs(l.sections.map(s=>text(s.html)).join(' ')).forEach(r=>refs.add(r))});DATA.books.forEach(b=>b.studies.forEach(s=>{refs.add(s.ref);extractRefs(text(s.html)+' '+s.distinction+' '+s.question).forEach(r=>refs.add(r))}));return [...refs].sort((a,b)=>{const x=parseRef(a),y=parseRef(b);return(x?.bi??99)-(y?.bi??99)||(x?.ch??0)-(y?.ch??0)||(x?.vs??0)-(y?.vs??0)}).map(r=>`<button class="pill" data-bible="${esc(r)}">${esc(r)}</button>`).join('')}
function renderLibrary(section='glossary'){if(!libItems.some(([s])=>s===section))section='glossary';let content='';const label=libItems.find(([s])=>s===section)[1];if(section==='glossary')content=`<h2>Words you may meet.</h2><p class="small muted">${DATA.glossary.length} definitions. Select a term to open it.</p><label class="field" style="margin:20px 0">Find a term<input id="glossaryQuery" type="search" value="${esc(glossaryQuery)}" placeholder="Covenant, assurance, baptism…"></label><div class="glossary" id="glossaryList">${glossaryHtml()}</div>`;else if(section==='scripture-memory'){const cats=['All',...new Set(DATA.memory.map(m=>m.category))];content=`<h2>Keep the Word in your heart.</h2><p class="small muted">${DATA.memory.length} KJV passages. A practiced marker records a review, not mastery.</p><label class="field" style="margin:20px 0">Subject<select id="memoryCategory">${cats.map(c=>`<option ${c===memoryCat?'selected':''}>${esc(c)}</option>`).join('')}</select></label><div class="cards" id="memoryCards">${memoryCards()}</div>`}else if(section==='scripture-index')content=`<h2>Passages to open.</h2><p class="small muted">Named references from the guides, principles, and examples. Each opens the KJV chapter for context.</p><div class="pills">${referenceIndex()}</div>`;else content=`<h2>${esc(label)}</h2><div class="prose">${section==='sources'?sourcesHtml():DATA.library[libNames[section]]||''}</div>`;return pageTop('Reference library','A little help at hand.','Definitions, Scripture memory, and supporting material for your reading.')+`<div class="wrap"><label class="field library-mobile">Reference section<select id="librarySelect">${libItems.map(([s,t])=>`<option value="${s}" ${s===section?'selected':''}>${esc(t)}</option>`).join('')}</select></label><div class="library-layout"><nav class="library-menu" aria-label="Reference sections">${libItems.map(([s,t])=>`<a href="#library/${s}" ${section===s?'aria-current="page"':''}>${esc(t)}</a>`).join('')}</nav><article class="library-article">${content}</article></div></div>`}
function renderReading(){return pageTop('Your reading','Return to what matters.','Your saved guides, recent place, and reading preferences.')+`<div class="wrap"><div class="stats"><div class="stat"><strong>${prefs.saved.length}</strong><span>Saved guides</span></div><div class="stat"><strong>${prefs.reviewed.length} / 66</strong><span>Guides reviewed</span></div><div class="stat"><strong>${prefs.practiced.length}</strong><span>Passages practiced</span></div><div class="stat"><strong>${prefs.lessons.length} / ${DATA.lessons.length}</strong><span>Lessons read</span></div></div>${prefs.last?`<div class="card" style="margin:20px 0"><span class="eyebrow">Continue reading</span><h3>${esc(prefs.last.label)}</h3><a class="button small" data-resume href="#${prefs.last.route}">Return to your place →</a></div>`:''}<section class="section" style="padding-top:25px"><div class="section-top"><h2>Saved guides</h2><a href="#books">Find a book →</a></div>${prefs.saved.length?`<div class="book-index">${DATA.books.filter(b=>prefs.saved.includes(b.slug)).map(bookTile).join('')}</div>`:'<p class="empty">Open a book guide and choose Save guide from its reading tools.</p>'}</section><section style="max-width:720px"><h2>Make yourself comfortable.</h2><div class="settings-row"><div><h3>Reading text size</h3><p>Applies to guide text and Bible passages.</p></div><div class="font-control"><button class="icon" data-size="-1" aria-label="Decrease text size">A−</button><output class="size-output">${prefs.size}px</output><button class="icon" data-size="1" aria-label="Increase text size">A+</button></div></div><div class="settings-row"><div><h3>Appearance</h3><p>Use a light page, a dark page, or your device setting.</p></div><label class="sr-only" for="themeSelect">Appearance</label><select id="themeSelect" class="select">${['system','light','dark'].map(t=>`<option value="${t}" ${prefs.theme===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div><div style="padding:26px 0"><h3 style="font-size:1.5rem">Keep a backup.</h3><p class="small muted">Progress stays in this browser. Export it before clearing browser data, or import your backup on another device. Importing a backup replaces the current reading record.</p><div class="backup-row"><button class="button secondary small" data-export>Export reading record</button><button class="button secondary small" data-import>Import backup</button></div><p class="small muted" style="margin-top:12px">${storageAvailable?'Changes are saved automatically when browser storage is available.':'Browser storage is unavailable. Export your record to keep changes.'}</p></div></section></div>`}

// Named references are linked after rendering so HTML and existing links remain intact.
const bookNames=[...BIBLE.map(b=>b.name),'Psalm'].sort((a,b)=>b.length-a.length).map(n=>n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|');
const refPattern=new RegExp('\\b(?:'+bookNames+')\\s+\\d{1,3}(?:[.:]\\d{1,3}(?:(?:\\s+to\\s+|[–-])\\d{1,3})?(?:,\\s*\\d{1,3})*)?(?:\\s+to\\s+\\d{1,3})?','g');
function extractRefs(t){return [...t.matchAll(new RegExp(refPattern.source,'g'))].map(m=>m[0])}
function parseRef(ref){const m=String(ref).trim().match(new RegExp('^('+bookNames+')\\s+(\\d+)(?:[.:](\\d+)(?:(?:\\s+to\\s+|[–-])(\\d+))?(?:,\\s*(\\d+))?)?(?:\\s+to\\s+(\\d+))?$','i'));if(!m)return null;const bi=bibleMap[m[1].toLowerCase()],ch=+m[2],vs=m[3]?+m[3]:null,ve=m[4]?+m[4]:vs,extra=m[5]?+m[5]:null;if(bi===undefined||!BIBLE[bi].chapters[ch-1])return null;const len=BIBLE[bi].chapters[ch-1].length;if(vs&&(vs<1||vs>len||ve<vs||ve>len||extra>len))return null;return {bi,ch,vs,ve,extra}}
function linkRefs(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(n){return n.parentElement.closest('a,button,script,style,select,option,.memory-quote')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){const s=n.textContent;const matches=[...s.matchAll(new RegExp(refPattern.source,'g'))].filter(m=>parseRef(m[0]));if(!matches.length)continue;let pos=0;const f=document.createDocumentFragment();for(const m of matches){f.append(s.slice(pos,m.index));const a=document.createElement('a');a.className='ref';a.href='#';a.dataset.bible=m[0];a.textContent=m[0];a.setAttribute('aria-label','Read '+m[0]+' in the KJV');f.append(a);pos=m.index+m[0].length}f.append(s.slice(pos));n.replaceWith(f)}}
let bibleState={bi:42,ch:1,vs:null,ve:null,extra:null};
$('#bibleBook').innerHTML=BIBLE.map((b,i)=>`<option value="${i}">${esc(b.name)}</option>`).join('');
function drawBible(){const s=bibleState,b=BIBLE[s.bi],chapter=b.chapters[s.ch-1];$('#bibleBook').value=s.bi;$('#bibleChapter').innerHTML=b.chapters.map((_,i)=>`<option value="${i+1}" ${i+1===s.ch?'selected':''}>${i+1}</option>`).join('');$('#bibleTitle').textContent=b.name+' '+s.ch;$('#bibleNote').textContent=s.vs?'The requested verses are highlighted. The whole chapter is shown for context.':'The whole chapter is shown. Use the chapter selector to continue.';$('#bibleText').innerHTML=chapter.map((v,i)=>`<p class="verse-line ${s.vs&&((i+1>=s.vs&&i+1<=s.ve)||i+1===s.extra)?'highlight':''}" id="verse-${i+1}"><sup>${i+1}</sup>${esc(v)}</p>`).join('');$('#biblePrev').disabled=s.bi===0&&s.ch===1;$('#bibleNext').disabled=s.bi===65&&s.ch===BIBLE[65].chapters.length;const target=s.vs?$('#verse-'+s.vs):null;if(target)setTimeout(()=>target.scrollIntoView({block:'center',behavior:'instant'}),0);else $('#bibleDialog').scrollTop=0}
function openBible(ref){const p=parseRef(ref);if(!p){toast('That reference could not be opened. Try a book and chapter.');return}bibleState=p;openDialog('bibleDialog');drawBible()}
function shiftBible(dir){let s=bibleState,ch=s.ch+dir,bi=s.bi;if(ch<1){bi--;if(bi<0)return;ch=BIBLE[bi].chapters.length}if(ch>BIBLE[bi].chapters.length){bi++;ch=1;if(bi>65)return}bibleState={bi,ch,vs:null,ve:null,extra:null};drawBible()}
$('#bibleBook').addEventListener('change',e=>{bibleState={bi:+e.target.value,ch:1,vs:null};drawBible()});$('#bibleChapter').addEventListener('change',e=>{bibleState={...bibleState,ch:+e.target.value,vs:null};drawBible()});$('#biblePrev').onclick=()=>shiftBible(-1);$('#bibleNext').onclick=()=>shiftBible(1);

const searchIndex=[];
DATA.books.forEach(b=>{searchIndex.push({title:b.name,kind:'Book overview',route:'books/'+b.slug,body:b.introText});b.helps.forEach((h,i)=>searchIndex.push({title:b.name+' · Help '+(i+1),kind:'Reading help',route:`books/${b.slug}/${i+1}`,body:h.text}))});
DATA.rules.forEach(r=>searchIndex.push({title:'Principle '+r.number+' · '+r.category,kind:'Reading principle',route:'principles/'+r.number,body:r.text}));
DATA.gospel.forEach((g,i)=>searchIndex.push({title:g.title,kind:'The gospel',route:'gospel/'+i,body:text(g.html)}));
DATA.examples.forEach((e,i)=>searchIndex.push({title:e.title,kind:'Worked example',route:'examples/'+i,body:e.question+' '+e.steps.flat().join(' ')}));
DATA.glossary.forEach(t=>searchIndex.push({title:t.term,kind:'Glossary',route:'library/glossary/'+slug(t.term),body:t.text}));
DATA.memory.forEach(m=>searchIndex.push({title:m.ref,kind:'Scripture memory · KJV',route:'library/scripture-memory/'+slug(m.ref),body:m.text}));
Object.entries(libNames).filter(([s])=>!['glossary','scripture-memory'].includes(s)).forEach(([s,name])=>{if(DATA.library[name])searchIndex.push({title:libItems.find(([id])=>id===s)[1],kind:'Reference',route:'library/'+s,body:text(DATA.library[name])})});
function excerpt(body,q){const i=body.toLowerCase().indexOf(q.toLowerCase()),start=Math.max(0,i-48),s=(start?'…':'')+body.slice(start,start+190)+(body.length>start+190?'…':'');if(!q)return esc(s);const at=s.toLowerCase().indexOf(q.toLowerCase());return at<0?esc(s):esc(s.slice(0,at))+'<mark>'+esc(s.slice(at,at+q.length))+'</mark>'+esc(s.slice(at+q.length))}
function searchNow(){const q=$('#globalSearch').value.trim(),lower=q.toLowerCase();if(!q){$('#globalResults').innerHTML='<p class="small muted">Find teaching on a subject, a book guide, or a definition. You can also open any KJV passage by reference.</p>';return}let items=searchIndex.map(i=>({...i,rank:i.title.toLowerCase()===lower?0:i.title.toLowerCase().includes(lower)?1:2})).filter(i=>(i.title+' '+i.body).toLowerCase().includes(lower)).sort((a,b)=>a.rank-b.rank);const total=items.length;items=items.slice(0,45);const p=parseRef(q);$('#globalResults').innerHTML=(p?`<button class="button" data-bible="${esc(q)}">Open ${esc(q)} · KJV</button>`:'')+`<p class="result-count">${total} results${total>45?' · showing the first 45':''}</p>`+items.map(i=>`<a class="search-result" href="#${i.route}"><small>${esc(i.kind)}</small><b>${esc(i.title)}</b><p>${excerpt(i.body,q)}</p></a>`).join('')+(!total&&!p?'<p class="empty">No matches. Try a shorter phrase or a book name.</p>':'')}
function openSearch(query=''){openDialog('searchDialog');$('#globalSearch').value=query;searchNow();$('#globalSearch').focus()}
$('#globalSearch').addEventListener('input',searchNow);

let focused=null;
function drawFocus(){const b=bookMap[focused.slug],i=focused.i;$('#focusTitle').textContent=b.name+' · Reading help '+(i+1);$('#focusBody').innerHTML=`<p class="small muted">Read this help with the biblical passage open.</p><div class="focus-copy">${b.helps[i].html}</div><div class="focus-bottom"><button class="button secondary small" data-focus-prev ${i===0?'disabled':''}>← Previous</button><span>${i+1} of ${b.helps.length}</span><button class="button small" data-focus-next>${i===b.helps.length-1?'Finish':'Next →'}</button></div>`;linkRefs($('#focusBody'))}
function changeSize(d){prefs.size=Math.max(17,Math.min(24,prefs.size+d));store();applySettings();$$('.size-output').forEach(e=>e.textContent=prefs.size+'px')}
let currentRoute='',resumeScroll=null,saveTimer;
function capturePlace(){if(!currentRoute)return;const [p,s]=currentRoute.split('/');let label=null;if(p==='books'&&bookMap[s])label=bookMap[s].name;else if(p==='gospel')label=DATA.gospel[+s||0]?.title;else if(p==='examples'&&DATA.examples[+s])label=DATA.examples[+s].title;else if(p==='principles')label='Reading principles';else if(p==='learn'&&DATA.lessons.some(l=>l.id===s))label=DATA.lessons.find(l=>l.id===s).title;else if(p==='doctrine'){const parts=currentRoute.split('/');const l=parts[1]==='course'?DATA.catechismCourse.find(l=>l.id===parts[2]):parts[1]==='further'?DATA.doctrineSupplements.find(l=>l.id===parts[2]):null;if(l)label=l.title}if(label){prefs.last={route:currentRoute,scroll:window.scrollY,label};store()}}
function render(){closeDialogs();const [p,s,sub]=path();if(p==='library'&&sub){if(s==='glossary')glossaryQuery='';if(s==='scripture-memory')memoryCat='All'}let html='';if(p==='home')html=renderHome();else if(p==='books')html=bookMap[s]?guide(bookMap[s]):renderBooks();else if(p==='principles')html=renderPrinciples();else if(p==='learn')html=renderLearn(s);else if(p==='doctrine')html=renderDoctrine(s);else if(p==='standards')html=renderStandards(s,sub);else if(p==='examples')html=renderExamples(s);else if(p==='gospel')html=renderGospel(s);else if(p==='library')html=renderLibrary(s);else if(p==='reading')html=renderReading();else html=pageTop('Page not found','Choose a place to begin.','That guide could not be found.')+'<div class="wrap"><a class="button" href="#books">Open the book guides</a></div>';$('#main').innerHTML=html;linkRefs($('#main'));currentRoute=path().join('/');const title=p==='books'&&bookMap[s]?bookMap[s].name:p==='gospel'?DATA.gospel[+s||0]?.title:p==='examples'&&DATA.examples[+s]?DATA.examples[+s].title:p==='home'?'':p==='reading'?'Your reading':p==='library'?'Reference library':p==='principles'?'Reading principles':p==='examples'?'Worked examples':'Book guides';document.title=(title?title+' | ':'')+'Bible Reading Helps';$$('[data-nav]').forEach(a=>a.toggleAttribute('aria-current',false));$$('[data-nav]').forEach(a=>{if(a.dataset.nav===p)a.setAttribute('aria-current','page')});$$('[data-mobile]').forEach(a=>{a.removeAttribute('aria-current');if(a.dataset.mobile===p)a.setAttribute('aria-current','page')});$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>{if(resumeScroll!==null){window.scrollTo({top:resumeScroll,behavior:'instant'});resumeScroll=null}else if(p==='books'&&sub){$('#help-'+CSS.escape(sub))?.scrollIntoView({block:'start',behavior:'instant'})}else if(p==='principles'&&s){if(ruleFilters.group!=='All'||ruleFilters.q){ruleFilters.group='All';ruleFilters.q='';$('#ruleList').innerHTML=rulesList();linkRefs($('#ruleList'));$('#ruleQuery').value='';$('#ruleGroup').value='All'}$('#principle-'+CSS.escape(s))?.scrollIntoView({block:'start',behavior:'instant'})}else if(p==='library'&&s==='glossary'&&sub){const term=$('#term-'+CSS.escape(sub));if(term){term.open=true;term.scrollIntoView({block:'center',behavior:'instant'})}}else if(p==='library'&&s==='scripture-memory'&&sub){$('#memory-'+CSS.escape(sub))?.closest('.card')?.scrollIntoView({block:'center',behavior:'instant'})}updateProgress();capturePlace()})}
function updateProgress(){const d=document.documentElement,range=d.scrollHeight-d.clientHeight;$('#progress').style.width=(range?Math.min(100,Math.max(0,window.scrollY/range*100)):0)+'%'}
window.addEventListener('scroll',()=>{updateProgress();clearTimeout(saveTimer);saveTimer=setTimeout(capturePlace,250)},{passive:true});
window.addEventListener('pagehide',capturePlace);window.addEventListener('hashchange',()=>{clearTimeout(saveTimer);render()});

document.addEventListener('click',e=>{
 const target=e.target.closest('button,a');if(!target)return;
 if(target.classList.contains('skip')){e.preventDefault();$('#main').focus();return}
 if(target.hasAttribute('data-close')){closeDialogs();return}
 if(target.hasAttribute('data-search')){openSearch();return}
 if(target.hasAttribute('data-menu')){openDialog('menuDialog');return}
 if(target.dataset.bible){e.preventDefault();openBible(target.dataset.bible);return}
 if(target.dataset.size){changeSize(+target.dataset.size);return}
 if(target.hasAttribute('data-print')){window.print();return}
 if(target.dataset.save){const s=target.dataset.save;prefs.saved=prefs.saved.includes(s)?prefs.saved.filter(x=>x!==s):[...prefs.saved,s];store();target.textContent=prefs.saved.includes(s)?'✓ Saved':'Save guide';target.setAttribute('aria-pressed',String(prefs.saved.includes(s)));toast(storageAvailable?(prefs.saved.includes(s)?'Guide saved. Find it in Your reading.':'Guide removed from saved guides.'):'Saved for this session. Export a backup to keep it.');return}
 if(target.dataset.review){const s=target.dataset.review;prefs.reviewed=prefs.reviewed.includes(s)?prefs.reviewed.filter(x=>x!==s):[...prefs.reviewed,s];store();target.textContent=prefs.reviewed.includes(s)?'✓ Reviewed':'Mark reviewed';target.setAttribute('aria-pressed',String(prefs.reviewed.includes(s)));toast(prefs.reviewed.includes(s)?'Guide marked reviewed.':'Review marker removed.');return}
 if(target.dataset.focus){focused={slug:target.dataset.focus,i:0};openDialog('focusDialog');drawFocus();return}
 if(target.hasAttribute('data-focus-prev')){if(focused.i>0){focused.i--;drawFocus()}return}
 if(target.hasAttribute('data-focus-next')){if(focused.i===focusTotal()-1)closeDialogs();else{focused.i++;drawFocus()}return}
 if(target.dataset.reveal){const q=$('#memory-'+CSS.escape(target.dataset.reveal));q.classList.toggle('hidden');const shown=!q.classList.contains('hidden');target.textContent=shown?'Hide passage':'Reveal passage';target.setAttribute('aria-expanded',String(shown));return}
 if(target.dataset.practiced){const s=target.dataset.practiced;prefs.practiced=prefs.practiced.includes(s)?prefs.practiced.filter(x=>x!==s):[...prefs.practiced,s];store();target.textContent=prefs.practiced.includes(s)?'✓ Practiced':'Mark practiced';target.setAttribute('aria-pressed',String(prefs.practiced.includes(s)));return}
 if(target.hasAttribute('data-clear-books')){bookFilters.q='';bookFilters.group='all';bookFilters.testament='all';$('#bookQuery').value='';$('#groupFilter').value='all';$('#testamentFilter').value='all';updateBookList();return}
 if(target.hasAttribute('data-export')){const blob=new Blob([JSON.stringify({...prefs,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Bible_Reading_Helps_Reading_Record.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Reading record exported.');return}
 if(target.hasAttribute('data-import')){$('#importFile').click();return}
 if(target.hasAttribute('data-resume')&&prefs.last)resumeScroll=prefs.last.scroll;
 if(target.dataset.scroll&&path()[0]==='books'){e.preventDefault();const el=$('#'+CSS.escape(target.dataset.scroll));el?.scrollIntoView({block:'start',behavior:'instant'});capturePlace();return}
 if(target.tagName==='A'&&target.getAttribute('href')?.startsWith('#')&&target.getAttribute('href')!=='#'){const h=target.getAttribute('href');if(h===location.hash){e.preventDefault();if(target.hasAttribute('data-standard-permalink'))scrollToStandardUnit(target.dataset.standardPermalink);else render()}else capturePlace()}
});
document.addEventListener('submit',e=>{if(e.target.id==='homeSearch'){e.preventDefault();const q=$('#homeQuery').value.trim(),b=DATA.books.find(b=>b.name.toLowerCase()===q.toLowerCase());if(b)location.hash='books/'+b.slug;else openSearch(q)}});
document.addEventListener('input',e=>{if(e.target.id==='bookQuery'){bookFilters.q=e.target.value;updateBookList()}if(e.target.id==='ruleQuery'){ruleFilters.q=e.target.value;$('#ruleList').innerHTML=rulesList();linkRefs($('#ruleList'))}if(e.target.id==='glossaryQuery'){glossaryQuery=e.target.value;$('#glossaryList').innerHTML=glossaryHtml();linkRefs($('#glossaryList'))}});
document.addEventListener('change',e=>{const id=e.target.id,v=e.target.value;if(id==='testamentFilter'){bookFilters.testament=v;updateBookList()}if(id==='groupFilter'){bookFilters.group=v;updateBookList()}if(id==='ruleGroup'){ruleFilters.group=v;$('#ruleList').innerHTML=rulesList();linkRefs($('#ruleList'))}if(id==='librarySelect')location.hash='library/'+v;if(id==='gospelSelect')location.hash='gospel/'+v;if(id==='memoryCategory'){memoryCat=v;$('#memoryCards').innerHTML=memoryCards()}if(id==='themeSelect'){prefs.theme=v;store();applySettings()}});
$('#importFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('File too large');const obj=JSON.parse(await f.text());if(obj.schema!==2||!Array.isArray(obj.saved)||!Array.isArray(obj.reviewed)||!Array.isArray(obj.practiced))throw Error('Wrong format');prefs=cleanData(obj);store();applySettings();render();toast('Reading record imported.')}catch{toast('That file is not a valid reading record.')}e.target.value=''});
window.addEventListener('keydown',e=>{const activeDialog=document.querySelector('dialog[open]');if(e.key==='Tab'&&activeDialog){const controls=[...activeDialog.querySelectorAll('button:not([disabled]),a[href],input:not([hidden]),select,[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=controls[0],last=controls.at(-1);if((e.shiftKey&&document.activeElement===first)||(!e.shiftKey&&document.activeElement===last)||!activeDialog.contains(document.activeElement)){e.preventDefault();(e.shiftKey?last:first)?.focus();return}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='/'&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();openSearch()}});

// Further study remains separate from the short reading helps so either can be
// used without hiding the other or replacing the passage's own context.
const lessonMap=Object.fromEntries(DATA.lessons.map(l=>[l.id,l]));
const lessonGroups=[...new Set(DATA.lessons.map(l=>l.group))];
if(!Array.isArray(prefs.lessons))prefs.lessons=[];
const doctrineThemes=[...new Set(DATA.books.flatMap(b=>b.studies.map(s=>s.theme)))].sort();
function studyMarkup(b,s,i){return `<details class="deeper-study" id="study-${i+1}"><summary><span class="study-summary"><span class="eyebrow">Further study ${String(i+1).padStart(2,'0')} · ${esc(s.theme)}</span><span class="study-title">${esc(s.title)}</span><span class="study-ref">${esc(s.ref)}</span></span></summary><div class="study-content prose"><a class="button secondary small" data-bible="${esc(s.ref)}" href="#">Open ${esc(s.ref)} · KJV</a>${s.html}<div class="study-distinction"><span class="study-label">A distinction to keep</span><p>${esc(s.distinction)}</p></div><div class="study-question"><span class="study-label">Work through the passage</span><p>${esc(s.question)}</p></div><p class="study-confession">${confessionLinks(s.confession)}</p><div class="study-links"><a href="#learn/${s.lesson}">Study the method →</a><a href="#books/${b.slug}/study-${i+1}" aria-label="Link to ${esc(s.title)}">Link to this study</a></div></div></details>`}
function deeperSection(b){return `<section class="further-section" id="further-study"><div class="further-heading"><span class="eyebrow">Stay with the passage</span><h2>Further study</h2><p>Follow the doctrinal connection and test it against the text. Open either study when you’re ready to work more closely.</p><button class="button secondary small" data-study-focus="${b.slug}">Study one at a time →</button></div>${b.studies.map((s,i)=>studyMarkup(b,s,i)).join('')}<p class="small muted study-end">A confessional reference explains the doctrinal connection. It remains subordinate to the Scripture being studied. <a href="#doctrine">Browse studies by doctrine →</a></p></section>`}
const shortGuide=guide;
guide=function(b){let content=shortGuide(b);content=content.replace('<nav class="guide-nav"',deeperSection(b)+'<nav class="guide-nav"');content=content.replace('<div class="sidebar-foot">',`<nav aria-label="Further studies"><a href="#books/${b.slug}/study-1" data-open-study="1">Further study</a><a href="#learn/literal-sense">The literal sense</a></nav><div class="sidebar-foot">`);content=content.replace(`${b.helps.length} reading helps</span>`,`${b.helps.length} helps · ${b.studies.length} further studies</span>`);return content}
function lessonCard(l,i){const done=prefs.lessons.includes(l.id);return `<a class="card card-link lesson-card ${done?'lesson-done':''}" href="#learn/${l.id}"><span class="eyebrow">Lesson ${String(i+1).padStart(2,'0')}${done?' · Read':''}</span><h3>${esc(l.title)}</h3><p>${esc(l.summary)}</p><span class="small">Open lesson →</span></a>`}
function renderLearn(id){const l=lessonMap[id];if(id&&!l)return pageTop('Study guide','That lesson could not be found.')+'<div class="wrap"><a class="button" href="#learn">All lessons</a></div>';if(!l)return pageTop('A course in careful reading','Understand what God has said.','Begin with the foundations, then work into genre, doctrine, and faithful application. Each lesson includes passages to examine and a question to work through.')+`<div class="wrap"><div class="learning-intro"><div><span class="eyebrow">A starting point and a way onward</span><h2>Read at the depth you need.</h2><p>Use the short book helps when you need your bearings. Take a lesson when a question needs fuller treatment. Then return to the passage and test what you’ve learned.</p></div><div class="learning-intro-actions"><a class="button" href="#learn/rightly-dividing">Begin the course →</a><a class="button secondary" href="#learn/literal-sense">What is the literal sense?</a></div></div><p class="result-count" id="lessonCount">${prefs.lessons.length} of ${DATA.lessons.length} lessons marked read. The marker records study, not mastery.</p>${lessonGroups.map((g,gi)=>`<section class="lesson-group"><div class="group-label"><h2>${gi+1}. ${esc(g)}</h2><small>${DATA.lessons.filter(l=>l.group===g).length} lessons</small></div><div class="cards">${DATA.lessons.filter(l=>l.group===g).map(l=>lessonCard(l,DATA.lessons.indexOf(l))).join('')}</div></section>`).join('')}<div class="learning-intro compact"><div><h3>Follow a doctrine through the Bible.</h3><p>The doctrine index brings together the further studies from every book.</p></div><a class="button secondary" href="#doctrine">Open the doctrine index →</a></div></div>`;
 const index=DATA.lessons.indexOf(l),done=prefs.lessons.includes(l.id),words=(l.summary+' '+l.sections.map(s=>text(s.html)).join(' ')+' '+l.answer).split(/\s+/).length;
 return `<div class="wrap"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#learn">Study guide</a><span>/</span><span>${esc(l.group)}</span></nav><header class="reader-head"><span class="eyebrow">Lesson ${String(index+1).padStart(2,'0')} of ${DATA.lessons.length} · ${Math.max(3,Math.ceil(words/150))} minute reading</span><h1 class="lesson-title">${esc(l.title)}</h1><p class="lesson-summary">${esc(l.summary)}</p></header><label class="field library-mobile lesson-jump">Another lesson<select id="lessonSelect">${DATA.lessons.map((s,i)=>`<option value="${s.id}" ${s.id===id?'selected':''}>${i+1}. ${esc(s.title)}</option>`).join('')}</select></label><div class="reader-layout"><aside class="reader-sidebar course-sidebar"><span class="sidebar-title">${esc(l.group)}</span><nav aria-label="Lessons in this group">${DATA.lessons.filter(s=>s.group===l.group).map(s=>`<a href="#learn/${s.id}" ${s.id===id?'aria-current="page"':''}>${esc(s.title)}</a>`).join('')}</nav><div class="sidebar-foot"><a href="#learn">All ${DATA.lessons.length} lessons →</a><p style="margin-top:14px">Read with your Bible open. The explanation should help you account for the words themselves.</p></div></aside><article class="reader prose"><div class="passage-panel"><span class="study-label">Read with the lesson</span><div class="pills">${l.refs.map(r=>`<button class="pill" data-bible="${esc(r)}">${esc(r)}</button>`).join('')}</div></div>${l.sections.map(s=>`<section class="lesson-section"><h2>${esc(s.title)}</h2>${s.html}</section>`).join('')}<section class="lesson-exercise"><span class="eyebrow">Try the reasoning yourself</span><h2>A question to work through</h2><p>${esc(l.exercise)}</p><details class="check-answer"><summary>Compare your reasoning</summary><div><p>${esc(l.answer)}</p></div></details></section><div class="confession-panel"><span class="study-label">Doctrinal connection</span><p>${confessionLinks(l.confession)}</p><p class="small muted">Use the confession as a subordinate guide. The passage supplies the evidence.</p></div><div class="row lesson-completion"><button class="button secondary small" data-lesson-done="${l.id}" aria-pressed="${done}">${done?'✓ Lesson marked read':'Mark lesson read'}</button><a class="small" href="#doctrine">Explore related book studies →</a></div><nav class="guide-nav">${index?`<a class="button secondary" href="#learn/${DATA.lessons[index-1].id}">← Previous lesson</a>`:'<a class="button secondary" href="#learn">← All lessons</a>'}${index<DATA.lessons.length-1?`<a class="button" href="#learn/${DATA.lessons[index+1].id}">Next lesson →</a>`:'<a class="button" href="#books">Return to the books →</a>'}</nav></article></div></div>`}
const doctrineFilter={theme:'All',q:''};
function doctrineRows(){const q=doctrineFilter.q.toLowerCase().trim();return DATA.books.flatMap(b=>b.studies.map((s,i)=>({b,s,i}))).filter(({b,s})=>(doctrineFilter.theme==='All'||s.theme===doctrineFilter.theme)&&(!q||(b.name+' '+s.title+' '+text(s.html)+' '+s.distinction).toLowerCase().includes(q)))}
function doctrineList(){const items=doctrineRows();return items.length?items.map(({b,s,i})=>`<a class="card card-link doctrine-card" href="#books/${b.slug}/study-${i+1}"><span class="eyebrow">${esc(s.theme)} · ${esc(b.name)}</span><h3>${esc(s.title)}</h3><p>${esc(s.distinction)}</p><span class="small">${esc(s.ref)} →</span></a>`).join(''):'<div class="empty">No studies match. Try another subject or clear the search.</div>'}
function renderDoctrine(){return pageTop('The doctrines Scripture teaches','Trace a truth through the books.','Find fuller studies by subject, then examine each passage in its own context. A shared doctrine does not make the passages interchangeable.')+`<div class="wrap"><div class="filters"><label class="field grow">Find a study<input id="doctrineQuery" type="search" placeholder="A doctrine, book, or question" value="${esc(doctrineFilter.q)}"></label><label class="field">Subject<select id="doctrineTheme">${['All',...doctrineThemes].map(t=>`<option ${t===doctrineFilter.theme?'selected':''}>${esc(t)}</option>`).join('')}</select></label><a class="button secondary small" href="#learn">Study the method →</a></div><p class="result-count" id="doctrineCount" aria-live="polite">${doctrineRows().length} further studies</p><div class="cards" id="doctrineList">${doctrineList()}</div></div>`}
function updateDoctrine(){ $('#doctrineList').innerHTML=doctrineList();$('#doctrineCount').textContent=doctrineRows().length+' further studies'}

const earlierHome=renderHome;
renderHome=function(){const content=earlierHome();const strip=`<section class="learning-strip"><div class="wrap row between"><p><strong>Want to read more closely?</strong> Begin with the literal sense, then learn to trace doctrine from the text.</p><a href="#learn">Open the study guide →</a></div></section>`;return content.replace('<section class="section"><div class="wrap">',strip+'<section class="section"><div class="wrap">')}
DATA.lessons.forEach(l=>searchIndex.push({title:l.title,kind:'Study guide · '+l.group,route:'learn/'+l.id,body:l.summary+' '+l.sections.map(s=>text(s.html)).join(' ')+' '+l.exercise+' '+l.answer+' '+l.confession}));
DATA.books.forEach(b=>b.studies.forEach((s,i)=>searchIndex.push({title:b.name+' · '+s.title,kind:'Further study · '+s.theme,route:`books/${b.slug}/study-${i+1}`,body:text(s.html)+' '+s.distinction+' '+s.question+' '+s.confession})));
const earlierRender=render;
render=function(){const returning=resumeScroll!==null;earlierRender();const [p,s,sub]=path();if(p==='learn'&&lessonMap[s])document.title=lessonMap[s].title+' | Bible Reading Helps';else if(p==='learn')document.title='Study guide | Bible Reading Helps';else if(p==='doctrine')document.title='Doctrine index | Bible Reading Helps';if(p==='books'&&sub?.startsWith('study-')){const el=$('#'+CSS.escape(sub));if(el){el.open=true;if(!returning)requestAnimationFrame(()=>{el.scrollIntoView({block:'start',behavior:'instant'});capturePlace()})}}};
function focusTotal(){const b=bookMap[focused.slug];return focused.kind==='study'?b.studies.length:b.helps.length}
drawFocus=function(){const b=bookMap[focused.slug],i=focused.i,deep=focused.kind==='study',entry=deep?b.studies[i]:b.helps[i];$('#focusTitle').textContent=b.name+' · '+(deep?'Further study':'Reading help')+' '+(i+1);$('#focusBody').innerHTML=`<p class="small muted">${deep?esc(entry.title):'Read this help with the biblical passage open.'}</p><div class="focus-copy">${deep?`<button class="button secondary small" data-bible="${esc(entry.ref)}">Read ${esc(entry.ref)}</button>`:''}${entry.html}${deep?`<div class="study-distinction"><span class="study-label">A distinction to keep</span><p>${esc(entry.distinction)}</p></div><div class="study-question"><span class="study-label">Work through the passage</span><p>${esc(entry.question)}</p></div>`:''}</div><div class="focus-bottom"><button class="button secondary small" data-focus-prev ${i===0?'disabled':''}>← Previous</button><span>${i+1} of ${focusTotal()}</span><button class="button small" data-focus-next>${i===focusTotal()-1?'Finish':'Next →'}</button></div>`;linkRefs($('#focusBody'))};

document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.studyFocus){focused={slug:target.dataset.studyFocus,i:0,kind:'study'};openDialog('focusDialog');drawFocus()}if(target.dataset.lessonDone){const id=target.dataset.lessonDone;prefs.lessons=prefs.lessons.includes(id)?prefs.lessons.filter(x=>x!==id):[...prefs.lessons,id];store();target.setAttribute('aria-pressed',String(prefs.lessons.includes(id)));target.textContent=prefs.lessons.includes(id)?'✓ Lesson marked read':'Mark lesson read';toast(prefs.lessons.includes(id)?'Lesson marked read. Return to the passage as often as needed.':'Lesson marker removed.')}});
document.addEventListener('change',e=>{if(e.target.id==='lessonSelect')location.hash='learn/'+e.target.value;if(e.target.id==='doctrineTheme'){doctrineFilter.theme=e.target.value;updateDoctrine()}});
document.addEventListener('input',e=>{if(e.target.id==='doctrineQuery'){doctrineFilter.q=e.target.value;updateDoctrine()}});

const standardsMap=Object.fromEntries(DATA.standards.map(d=>[d.id,d]));
function confessionLinks(value){return esc(value).replace(/\b(WCF|WLC|WSC)\s+(\d+)(?:\.(\d+))?/g,(m,k,n,p)=>`<a href="#standards/${k.toLowerCase()}/${n}${p?'/'+p:''}">${m}</a>`)}
function standardsCards(kind){return DATA.standards.filter(d=>d.kind===kind).map(d=>`<a class="card card-link" href="#standards/${d.id}/1"><span class="eyebrow">${d.kind==='standard'?'Doctrinal Standard':'Related historical document'}</span><h3>${esc(d.title)}</h3><p>${d.sections.length} ${d.id==='wcf'?'chapters':d.id==='wlc'||d.id==='wsc'?'questions':'sections'}</p><span>Read the complete text →</span></a>`).join('')}
function renderStandards(id,number){const d=standardsMap[id];if(!d)return pageTop('The Westminster Standards','Read the doctrine at its source.','The complete Confession and both Catechisms, with their Scripture proofs. All eight historical texts here come solely from thewestminsterstandard.org.')+`<div class="wrap"><div class="learning-intro"><div><h2>Scripture is the supreme rule.</h2><p>The Standards summarize what Scripture teaches. Read them as subordinate standards, and distinguish their historical wording from the companion’s explanations.</p></div><a class="button secondary" href="#doctrine">Named doctrines →</a></div><h2>The three doctrinal Standards</h2><div class="cards">${standardsCards('standard')}</div><h2 style="margin-top:48px">Related documents</h2><p>Published alongside the Standards on the source site. These documents have different historical purposes and aren’t presented as additional catechisms or chapters of the Confession.</p><div class="cards">${standardsCards('associated')}</div><p class="small muted" style="margin-top:28px">Historical spelling, punctuation, and wording are retained. Navigation and duplicate headings are omitted. Numbered paragraphs are arranged by their numbers. Use the source link on each document to compare the website’s text.</p></div>`;
const n=Math.max(1,Math.min(d.sections.length,+number||1)),s=d.sections[n-1];return `<div class="wrap"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#standards">Westminster Standards</a><span>/</span><span>${esc(d.short)}</span></nav><header class="reader-head"><span class="eyebrow">${d.kind==='standard'?'Doctrinal Standard':'Related historical document'} · Complete text included</span><h1 class="lesson-title">${esc(d.title)}</h1><p class="small"><a href="${esc(d.source)}" target="_blank" rel="noopener noreferrer">Source at thewestminsterstandard.org ↗</a></p></header><div class="standards-tools"><label class="field grow">Document<select id="standardDocument">${DATA.standards.map(x=>`<option value="${x.id}" ${x===d?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label class="field grow">${d.id==='wcf'?'Chapter':d.id==='wlc'||d.id==='wsc'?'Question':'Section'}<select id="standardSection" data-document="${d.id}">${d.sections.map(x=>`<option value="${x.number}" ${x===s?'selected':''}>${x.number}. ${esc(x.units[0]?.question||x.title)}</option>`).join('')}</select></label><div class="font-control"><button class="icon" data-size="-1" aria-label="Decrease text size">A−</button><output class="size-output">${prefs.size}px</output><button class="icon" data-size="1" aria-label="Increase text size">A+</button></div></div><div class="standards-layout"><aside class="standards-sidebar"><h2>Find a passage</h2><label class="field">Search this document<input type="search" id="standardSearch" data-document="${d.id}" placeholder="A word or phrase"></label><div id="standardResults" aria-live="polite"><p class="small muted">Search the full document, including the Scripture proofs.</p></div><p class="small"><a href="#doctrine">Explain the doctrines →</a></p></aside><article class="reader prose standards-text"><span class="eyebrow">${n} of ${d.sections.length}</span><h2>${esc(s.title)}</h2>${s.units.map(u=>`<section class="standard-unit" id="standard-unit-${u.number}">${u.sectionHeading?`<h3 class="catechism-division">${esc(u.sectionHeading)}</h3>`:''}${u.question?`<h3>Q. ${u.number}. ${esc(u.question)}</h3>`:d.id==='wcf'?`<h3>Paragraph ${u.number}</h3>`:''}<div class="standard-wording">${u.html}</div>${u.proofHtml?`<details class="standard-proofs"><summary>Scripture proofs</summary><div>${u.proofHtml}</div></details>`:''}<a class="small muted" data-standard-permalink="${u.number}" href="#standards/${d.id}/${n}/${u.number}" aria-label="Link to ${esc(d.short)} ${n}.${u.number}">Link to this ${d.id==='wcf'?'paragraph':u.question?'answer':'passage'}</a></section>`).join('')}<nav class="guide-nav">${n>1?`<a class="button secondary" href="#standards/${d.id}/${n-1}">← Previous</a>`:'<a class="button secondary" href="#standards">All documents</a>'}${n<d.sections.length?`<a class="button" href="#standards/${d.id}/${n+1}">Next →</a>`:'<a class="button" href="#standards">All documents →</a>'}</nav></article></div></div>`}
const subjectDoctrinePage=renderDoctrine;
renderDoctrine=function(id){const p=DATA.doctrines.find(x=>x.id===id);if(p)return `<div class="wrap"><nav class="breadcrumbs"><a href="#doctrine">Named doctrines</a><span>/</span><span>${esc(p.title)}</span></nav><header class="reader-head"><span class="eyebrow">Reformed Presbyterian doctrine · Editorial explanation</span><h1 class="lesson-title">${esc(p.title)}</h1></header><article class="reader prose doctrine-definition"><h2>What the doctrine teaches</h2><p>${esc(p.definition)}</p><h2>A distinction to keep</h2><p>${esc(p.guard)}</p><div class="passage-panel"><span class="study-label">Begin with Scripture</span><p><button class="button secondary small" data-bible="${esc(p.ref)}">Read ${esc(p.ref)} · KJV</button></p><p>Read the whole passage. Explain how its words support the doctrine before moving to its implications.</p></div><div class="confession-panel"><span class="study-label">Read the subordinate Standards</span><p>${confessionLinks(p.confession)}</p></div><p><a href="#learn/literal-sense">Study the literal sense</a> · <a href="#books">Return to the book guides</a></p></article></div>`;
return subjectDoctrinePage().replace('<div class="wrap"><div class="filters">',`<div class="wrap"><div class="learning-intro"><div><h2>Know what the doctrine is called.</h2><p>These entries state the Reformed Presbyterian teaching, explain a distinction that prevents a common error, and open the relevant Scripture and Westminster text. The confession remains subordinate to Scripture.</p></div><a class="button secondary" href="#standards">Read the full Standards →</a></div><div class="cards named-doctrines">${DATA.doctrines.map(p=>`<a class="card card-link" href="#doctrine/${p.id}"><h3>${esc(p.title)}</h3><p>${esc(p.definition)}</p><span class="small">Scripture, explanation, and Standards →</span></a>`).join('')}</div><h2 style="margin-top:48px">Work through the passages</h2><div class="filters">`)};
const previousLinkRefs=linkRefs;
linkRefs=function(root){previousLinkRefs(root);const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('a,button,script,style,select,option,.standard-wording,.standard-proofs')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});const nodes=[];while(walker.nextNode())if(/\b(WCF|WLC|WSC)\s+\d/.test(walker.currentNode.textContent))nodes.push(walker.currentNode);for(const node of nodes){const span=document.createElement('span');span.innerHTML=confessionLinks(node.textContent);node.replaceWith(span)}};
sourcesHtml=function(){return `<p>This companion teaches from a Reformed Presbyterian position. Its explanations are editorial and must be tested by Scripture. The Confession and Catechisms are subordinate standards, not additional revelation.</p><h3>Westminster source</h3><p>All Westminster texts in this edition come solely from <a href="https://thewestminsterstandard.org/" target="_blank" rel="noopener noreferrer">thewestminsterstandard.org</a>. The complete texts, including the published Scripture proofs, are built into this file for offline reading.</p><p><a href="#standards">Read all the Standards and related documents →</a></p><h3>Doctrinal commitments</h3><p>The teaching follows Westminster covenant theology, infant baptism, Presbyterian government, the regulative principle, and Reformed Presbyterian exclusive, unaccompanied psalmody. The guide's amillennial reading is identified as an interpretation. The Standards don't prescribe a particular millennial scheme.</p><h3>Text and explanation</h3><p>Historical wording is preserved in the Standards reader. Editorial doctrine entries explain terms and distinctions in contemporary language. KJV Scripture is included separately, with its verse wording preserved.</p><p>${DATA.lessons.length} lessons and ${DATA.books.reduce((n,b)=>n+b.studies.length,0)} further studies accompany all 66 books. There are ${DATA.doctrines.length} named doctrine entries.</p>`};
libItems.unshift(['standards','Westminster Standards']);
const oldLibrary=renderLibrary;renderLibrary=function(section){return section==='standards'?renderStandards():oldLibrary(section)};
DATA.standards.forEach(d=>d.sections.forEach(s=>s.units.forEach(u=>searchIndex.push({title:d.short+' '+s.number+(d.id==='wcf'?'.'+u.number:'')+' · '+(u.question||s.title),kind:'Westminster source text',route:`standards/${d.id}/${s.number}${d.id==='wcf'?'/'+u.number:''}`,body:u.text+' '+u.proofs.join(' ')}))));
DATA.doctrines.forEach(p=>searchIndex.push({title:p.title,kind:'Named doctrine',route:'doctrine/'+p.id,body:p.definition+' '+p.guard+' '+p.confession}));
const renderBeforeStandards=render;
function scrollToStandardUnit(unit){
 const target=document.getElementById('standard-unit-'+unit);
 if(!target)return;
 target.setAttribute('tabindex','-1');
 target.focus({preventScroll:true});
 target.scrollIntoView({block:'start',behavior:'instant'});
}
render=function(){
 const returning=resumeScroll!==null;
 renderBeforeStandards();
 const [p,id,n,u]=path();
 if(p==='standards'){
  document.title=(standardsMap[id]?.title||'Westminster Standards')+' | Bible Reading Helps';
  const documentData=standardsMap[id];
  const section=documentData?.sections[Math.max(1,Math.min(documentData.sections.length,+n||1))-1];
  // Older question links omit a unit because each question has just one answer.
  const unit=u||((id==='wlc'||id==='wsc')?section?.units[0]?.number:null);
  if(unit&&(!returning||u)){
   const targetRoute=location.hash;
   document.fonts.ready.then(()=>requestAnimationFrame(()=>{
    if(location.hash===targetRoute)scrollToStandardUnit(unit);
   }));
  }
 }
};

document.addEventListener('change',e=>{if(e.target.id==='standardDocument')location.hash='standards/'+e.target.value+'/1';if(e.target.id==='standardSection')location.hash='standards/'+e.target.dataset.document+'/'+e.target.value});
document.addEventListener('input',e=>{if(e.target.id!=='standardSearch')return;const q=e.target.value.toLowerCase().trim(),d=standardsMap[e.target.dataset.document];const results=q?d.sections.flatMap(s=>s.units.filter(u=>(u.question+' '+u.text+' '+u.proofs.join(' ')).toLowerCase().includes(q)).map(u=>({s,u}))):[];$('#standardResults').innerHTML=q?`<p class="small muted">${results.length} matches${results.length>60?' · first 60 shown':''}</p>`+results.slice(0,60).map(({s,u})=>`<a class="search-result" href="#standards/${d.id}/${s.number}${d.id==='wcf'?'/'+u.number:''}"><b>${d.short} ${s.number}${d.id==='wcf'?'.'+u.number:''}</b><p>${excerpt(u.question||u.text,q)}</p></a>`).join(''):'<p class="small muted">Search the full document, including the Scripture proofs.</p>'});

// Browse in small sets. Full explanations retain their own stable routes.
const doctrineGroups={
'Scripture':['sola-scriptura','inspiration','literal-sense','necessary-consequence'],
'God and creation':['trinity','divine-attributes','creation','providence'],
'Covenant and Christ':['covenant-works','covenant-grace','christology'],
'Salvation':['total-depravity','election','atonement','effectual-calling','justification','adoption','sanctification','repentance','perseverance'],
'Church and worship':['regulative-principle','exclusive-psalmody','sabbath','church','presbyterian-government','means-of-grace','baptism','lords-supper','cessationism'],
'Christian life and last things':['christian-liberty','general-equity','civil-magistrate','last-things']};
const browseState={q:'',group:'All',page:1,mode:'names'};
const PAGE_SIZE=8;
function browseRows(){const q=browseState.q.trim().toLowerCase();return browseState.mode==='names'?DATA.doctrines.filter(p=>(browseState.group==='All'||doctrineGroups[browseState.group]?.includes(p.id))&&(!q||(p.title+' '+p.definition+' '+p.guard+' '+p.confession).toLowerCase().includes(q))):DATA.books.flatMap(b=>b.studies.map((s,i)=>({b,s,i}))).filter(({b,s})=>(browseState.group==='All'||s.theme===browseState.group)&&(!q||(b.name+' '+s.title+' '+text(s.html)+' '+s.distinction+' '+s.confession).toLowerCase().includes(q)))}
function browseResults(){const rows=browseRows(),pages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));browseState.page=Math.min(pages,Math.max(1,browseState.page));const start=(browseState.page-1)*PAGE_SIZE;return `<p class="result-count" role="status">${rows.length?`${start+1}–${Math.min(start+PAGE_SIZE,rows.length)} of ${rows.length} ${browseState.mode==='names'?'doctrines':'passage studies'}`:'No matches. Try a broader search.'}</p><div class="browse-rows">${rows.slice(start,start+PAGE_SIZE).map(p=>browseState.mode==='names'?`<a class="browse-row" href="#doctrine/${p.id}"><span><strong>${esc(p.title)}</strong><small>${esc(Object.keys(doctrineGroups).find(k=>doctrineGroups[k].includes(p.id)))}</small></span><span aria-hidden="true">→</span></a>`:`<a class="browse-row" href="#books/${p.b.slug}/study-${p.i+1}"><span><small>${esc(p.b.name)} · ${esc(p.s.theme)}</small><strong>${esc(p.s.title)}</strong><small>${esc(p.s.ref)}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div>${rows.length>PAGE_SIZE?`<nav class="browse-pagination" aria-label="Result pages"><button class="button secondary small" data-browse-page="${browseState.page-1}" ${browseState.page===1?'disabled':''}>← Previous</button><span>Page ${browseState.page} of ${pages}</span><button class="button secondary small" data-browse-page="${browseState.page+1}" ${browseState.page===pages?'disabled':''}>Next →</button></nav>`:''}`}
function updateBrowse(focus=false){const el=$('#browseResults');el.innerHTML=browseResults();if(focus){el.focus({preventScroll:true});el.scrollIntoView({block:'start',behavior:'instant'})}}
const doctrinalDetail=renderDoctrine;
renderDoctrine=function(id){if(DATA.doctrines.some(p=>p.id===id))return doctrinalDetail(id);const mode=id==='studies'?'studies':'names';if(browseState.mode!==mode){browseState.mode=mode;browseState.group='All';browseState.page=1}const cats=mode==='names'?Object.keys(doctrineGroups):doctrineThemes;return pageTop('Reformed Presbyterian teaching','Explore doctrine.','Choose a doctrine for its explanation, or follow a passage study through a book of Scripture.')+`<div class="wrap browse-shell"><nav class="view-switch" aria-label="Doctrine views"><a href="#doctrine" ${mode==='names'?'aria-current="page"':''}>Named doctrines <small>33</small></a><a href="#doctrine/studies" ${mode==='studies'?'aria-current="page"':''}>Passage studies <small>132</small></a></nav><div class="browse-filters"><label class="field grow">${mode==='names'?'Find a doctrine':'Find a passage study'}<input type="search" id="browseQuery" value="${esc(browseState.q)}" placeholder="${mode==='names'?'Justification, worship, covenant…':'Romans, assurance, resurrection…'}"></label><label class="field">Subject<select id="browseGroup">${['All',...cats].map(g=>`<option ${g===browseState.group?'selected':''}>${esc(g)}</option>`).join('')}</select></label><button class="button secondary small" data-browse-clear>Reset</button></div><div id="browseResults" tabindex="-1">${browseResults()}</div><div class="quiet-links"><a href="#standards">Read the full Standards →</a><a href="#learn/literal-sense">Learn how to read a passage →</a></div></div>`};
const fullLesson=renderLearn;
renderLearn=function(id){if(id)return fullLesson(id);return pageTop('Learn to read Scripture','Take the next lesson.','Start with the foundations or open the subject you need. Each lesson has passages to examine and a question to work through.')+`<div class="wrap browse-shell"><div class="start-course"><div><span class="eyebrow">New here?</span><h2>Begin with the text.</h2><p>Learn what it means to rightly divide the word of truth.</p></div><a class="button" href="#learn/rightly-dividing">Start the course →</a></div><label class="field course-search">Find a lesson<input id="courseQuery" type="search" placeholder="Literal sense, prophecy, application…"></label><p class="small muted">${prefs.lessons.length} of ${DATA.lessons.length} lessons marked read</p><div id="courseGroups">${compactCourse()}</div><div class="quiet-links"><a href="#examples">See worked examples →</a><a href="#doctrine">Explore doctrine →</a></div></div>`};
function compactCourse(q=''){q=q.toLowerCase().trim();return lessonGroups.map((g,gi)=>{const ls=DATA.lessons.filter(l=>l.group===g&&(!q||(l.title+' '+l.summary+' '+l.sections.map(s=>text(s.html)).join(' ')).toLowerCase().includes(q)));return ls.length?`<details class="browse-group" ${q?'open':''}><summary><span><small>Part ${gi+1}</small><strong>${esc(g)}</strong></span><span class="group-count">${ls.length} lessons</span></summary><div>${ls.map(l=>`<a class="browse-row" href="#learn/${l.id}"><span class="lesson-number">${String(DATA.lessons.indexOf(l)+1).padStart(2,'0')}</span><span><strong>${esc(l.title)}</strong><small>${prefs.lessons.includes(l.id)?'✓ Marked read':esc(l.summary)}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div></details>`:''}).join('')||'<p class="empty">No lessons match. Try another word.</p>'}
renderHome=function(){const last=prefs.last;return `<section class="home-hero"><div class="wrap home-simple"><span class="eyebrow">A Reformed reading companion</span><h1 class="hero-title">Read with care.<br><em>Know the Word.</em></h1><p class="hero-lead">Open a book guide beside your Bible, or take a lesson in reading Scripture.</p><form id="homeSearch" class="home-search" role="search"><label class="sr-only" for="homeQuery">Search the companion</label><input id="homeQuery" type="search" placeholder="A book, doctrine, or Bible passage" autocomplete="off">${icon('search')}<button class="sr-only" type="submit">Search</button></form>${last?`<a class="continue-link" data-resume href="#${last.route}">Return to ${esc(last.label)} →</a>`:'<a class="continue-link" href="#learn/rightly-dividing">New to Bible study? Start here →</a>'}</div></section><div class="wrap home-destinations"><a class="destination" href="#books"><span class="eyebrow">Read</span><h2>Book guides</h2><p>Find your place in any of the Bible’s 66 books.</p><span>Choose a book →</span></a><a class="destination" href="#learn"><span class="eyebrow">Learn</span><h2>Study guide</h2><p>Work through a lesson at your own pace.</p><span>Explore 24 lessons →</span></a><a class="destination" href="#doctrine"><span class="eyebrow">Understand</span><h2>Doctrine</h2><p>Find a named doctrine and examine its biblical grounds.</p><span>Browse by subject →</span></a><a class="destination" href="#standards"><span class="eyebrow">Reference</span><h2>Westminster Standards</h2><p>Read the Confession and both Catechisms.</p><span>Open the texts →</span></a></div><section class="section"><div class="wrap"><div class="section-top"><h2>Open a familiar book.</h2><a href="#books">All 66 books →</a></div><div class="book-index familiar-books">${['genesis','psalms','matthew','john','romans','revelation'].map(s=>bookTile(bookMap[s])).join('')}</div><div class="quiet-links"><a href="#gospel">The gospel →</a><a href="#examples">Try a worked example →</a></div></div></section>`};
const originalBookList=bookListHtml;
bookListHtml=function(books){if(bookFilters.q||bookFilters.group!=='all')return originalBookList(books);return groups.filter(g=>books.some(b=>b.group===g)).map(g=>`<details class="browse-group book-section"><summary><span><strong>${esc(g)}</strong></span><span class="group-count">${books.filter(b=>b.group===g).length} books</span></summary><div class="book-index">${books.filter(b=>b.group===g).map(bookTile).join('')}</div></details>`).join('')||'<div class="empty">No books match. Clear the filters to start again.</div>'};
const expandedGuide=guide;
guide=function(b){const holder=document.createElement('div');holder.innerHTML=expandedGuide(b);holder.querySelectorAll('.help').forEach((section,i)=>{const details=document.createElement('details');details.className='help help-disclosure';details.id=section.id;details.innerHTML=`<summary><span class="help-label">${String(i+1).padStart(2,'0')}</span><span>${esc(shortTitle(b.helps[i].text))}</span></summary><div class="help-copy">${b.helps[i].html}<a class="small muted" href="#books/${b.slug}/${i+1}">Link to this help</a></div>`;section.replaceWith(details)});const tools=holder.querySelector('.reader-tools');tools?.querySelector('.tool-content')?.insertAdjacentHTML('beforeend','<button class="button secondary small" data-toggle-helps aria-expanded="false">Expand all helps</button>');tools?.insertAdjacentHTML('afterend',`<label class="field guide-jump">Jump to a section<select id="guideJump" data-book="${b.slug}"><option value="">Overview</option>${b.helps.map((h,i)=>`<option value="${i+1}">${i+1}. ${esc(shortTitle(h.text))}</option>`).join('')}${b.studies.map((s,i)=>`<option value="study-${i+1}">Further study ${i+1}. ${esc(s.title)}</option>`).join('')}</select></label>`);return holder.innerHTML};
const fullRules=rulesList;
rulesList=function(){const holder=document.createElement('div');holder.innerHTML=fullRules();holder.querySelectorAll('.help').forEach(section=>{const n=+section.id.replace('principle-',''),r=DATA.rules.find(r=>r.number===n);const details=document.createElement('details');details.className='help help-disclosure';details.id=section.id;details.innerHTML=`<summary><span class="help-label">${String(n).padStart(2,'0')}</span><span>${esc(r.category)}<small>${esc(shortTitle(r.text))}</small></span></summary><div class="help-copy">${r.html}<a class="small muted" href="#principles/${n}">Link to this principle</a></div>`;section.replaceWith(details)});return holder.innerHTML};
const fullExamples=renderExamples;
renderExamples=function(n){if(n!==undefined)return fullExamples(n);return pageTop('Learn with a passage open','Worked examples.','Choose a question and follow the reasoning through the text.')+`<div class="wrap browse-shell"><div class="browse-rows">${DATA.examples.map((e,i)=>`<a class="browse-row" href="#examples/${i}"><span class="lesson-number">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(e.title)}</strong><small>${esc(e.ref)}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div></div>`};
const previousUXRender=render;
render=function(){previousUXRender();const [p,s,sub]=path();if(p==='books'&&bookMap[s]&&sub){const d=$('#'+CSS.escape(sub.startsWith('study-')?sub:'help-'+sub));if(d instanceof HTMLDetailsElement)d.open=true;const jump=$('#guideJump');if(jump)jump.value=sub}if(p==='principles'&&s){const d=$('#principle-'+CSS.escape(s));if(d instanceof HTMLDetailsElement)d.open=true}if(p==='standards'&&window.innerWidth<=800){const sidebar=$('.standards-sidebar');if(sidebar){const disclosure=document.createElement('details');disclosure.className='mobile-document-search';disclosure.innerHTML='<summary>Search this document</summary>';const h=sidebar.querySelector('h2');h?.remove();const label=sidebar.querySelector('label');if(label)disclosure.append(label);const results=sidebar.querySelector('#standardResults');if(results)disclosure.append(results);sidebar.prepend(disclosure)}}};
document.addEventListener('input',e=>{if(e.target.id==='browseQuery'){browseState.q=e.target.value;browseState.page=1;updateBrowse()}if(e.target.id==='courseQuery')$('#courseGroups').innerHTML=compactCourse(e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='browseGroup'){browseState.group=e.target.value;browseState.page=1;updateBrowse()}if(e.target.id==='guideJump')location.hash='books/'+e.target.dataset.book+(e.target.value?'/'+e.target.value:'')});
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.browsePage){browseState.page=+b.dataset.browsePage;updateBrowse(true)}if(b.hasAttribute('data-browse-clear')){browseState.q='';browseState.group='All';browseState.page=1;$('#browseQuery').value='';$('#browseGroup').value='All';updateBrowse()}if(b.dataset.scroll){const d=document.getElementById(b.dataset.scroll);if(d instanceof HTMLDetailsElement)d.open=true}});
const referencePages={glossary:1,memory:1},referenceTargets={glossary:null,memory:null};
function referencePager(kind,count,page){const pages=Math.ceil(count/10);return pages>1?`<nav class="browse-pagination reference-pages" aria-label="${kind==='glossary'?'Glossary':'Scripture memory'} pages"><button class="button secondary small" data-reference-kind="${kind}" data-reference-page="${page-1}" ${page===1?'disabled':''}>← Previous</button><span>Page ${page} of ${pages}</span><button class="button secondary small" data-reference-kind="${kind}" data-reference-page="${page+1}" ${page===pages?'disabled':''}>Next →</button></nav>`:''}
const fullGlossary=glossaryHtml;
glossaryHtml=function(){const holder=document.createElement('div');holder.innerHTML=fullGlossary();const rows=[...holder.children],target=path()[2];if(!target)referenceTargets.glossary=null;if(target&&!glossaryQuery&&referenceTargets.glossary!==target){referenceTargets.glossary=target;const i=rows.findIndex(n=>n.id==='term-'+target);if(i>=0)referencePages.glossary=Math.floor(i/10)+1}const page=referencePages.glossary=Math.max(1,Math.min(referencePages.glossary,Math.ceil(rows.length/10)||1));return rows.slice((page-1)*10,page*10).map(n=>n.outerHTML).join('')+referencePager('glossary',rows.length,page)};
const fullMemoryCards=memoryCards;
memoryCards=function(){const holder=document.createElement('div');holder.innerHTML=fullMemoryCards();const rows=[...holder.children],target=path()[2];if(!target)referenceTargets.memory=null;if(target&&referenceTargets.memory!==target){referenceTargets.memory=target;const i=rows.findIndex(n=>n.querySelector('#memory-'+CSS.escape(target)));if(i>=0)referencePages.memory=Math.floor(i/10)+1}const page=referencePages.memory=Math.max(1,Math.min(referencePages.memory,Math.ceil(rows.length/10)||1));return rows.slice((page-1)*10,page*10).map(n=>n.outerHTML).join('')+referencePager('memory',rows.length,page)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-reference-kind]');if(!b)return;const kind=b.dataset.referenceKind;referencePages[kind]=+b.dataset.referencePage;const el=kind==='glossary'?$('#glossaryList'):$('#memoryCards');el.innerHTML=kind==='glossary'?glossaryHtml():memoryCards();linkRefs(el);el.setAttribute('tabindex','-1');el.focus({preventScroll:true});el.scrollIntoView({block:'start',behavior:'instant'})});
document.addEventListener('input',e=>{if(e.target.id==='glossaryQuery'){referencePages.glossary=1;$('#glossaryList').innerHTML=glossaryHtml();linkRefs($('#glossaryList'))}});
let printDisclosures=[];
window.addEventListener('beforeprint',()=>{printDisclosures=[...document.querySelectorAll('main details:not([open])')];printDisclosures.forEach(d=>d.open=true)});
window.addEventListener('afterprint',()=>{printDisclosures.forEach(d=>d.open=false);printDisclosures=[]});

document.addEventListener('click',e=>{const b=e.target.closest('[data-toggle-helps]');if(!b)return;const expand=b.getAttribute('aria-expanded')!=='true';$$('.help-disclosure').forEach(d=>d.open=expand);b.setAttribute('aria-expanded',String(expand));b.textContent=expand?'Collapse all helps':'Expand all helps'});

const catechismMap=Object.fromEntries(DATA.catechismCourse.map(l=>[l.id,l]));
const supplementMap=Object.fromEntries(DATA.doctrineSupplements.map(l=>[l.id,l]));
const courseBrowse={q:'',unit:'All',page:1};
const courseFinished=()=>prefs.doctrineRead.filter(id=>catechismMap[id]).length;
function courseRows(){const q=courseBrowse.q.toLowerCase().trim();return DATA.catechismCourse.filter(l=>(courseBrowse.unit==='All'||courseUnit(l).title===courseBrowse.unit)&&(!q||(l.title+' '+l.number+' '+l.teach+' '+l.argument+' '+l.guard+' '+standardsMap.wsc.sections[l.number-1].units[0].text).toLowerCase().includes(q)))}
function courseUnit(l){return DATA.courseUnits.find(g=>l.number>=g.start&&l.number<=g.end)}
function courseResults(){const rows=courseRows(),pages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));courseBrowse.page=Math.min(pages,Math.max(1,courseBrowse.page));const start=(courseBrowse.page-1)*PAGE_SIZE;return `<p class="result-count" role="status">${rows.length?`${start+1}–${Math.min(start+PAGE_SIZE,rows.length)} of ${rows.length} lessons`:'No lessons match. Try another search.'}</p><div class="browse-rows">${rows.slice(start,start+PAGE_SIZE).map(l=>`<a class="browse-row" href="#doctrine/course/${l.id}"><span class="lesson-number">${String(l.number).padStart(2,'0')}</span><span><strong>${esc(l.title)}</strong><small>${esc(courseUnit(l).title)}${prefs.doctrineRead.includes(l.id)?' · ✓ Read':''}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div>${rows.length>PAGE_SIZE?`<nav class="browse-pagination" aria-label="Catechism lesson pages"><button class="button secondary small" data-course-page="${courseBrowse.page-1}" ${courseBrowse.page===1?'disabled':''}>← Previous</button><span>Page ${courseBrowse.page} of ${pages}</span><button class="button secondary small" data-course-page="${courseBrowse.page+1}" ${courseBrowse.page===pages?'disabled':''}>Next →</button></nav>`:''}`}
function refreshCourse(focus=false){const el=$('#catechismResults');el.innerHTML=courseResults();if(focus){el.focus({preventScroll:true});el.scrollIntoView({block:'start',behavior:'instant'})}}
function doctrineViewLinks(mode){return `<nav class="doctrine-views" aria-label="Doctrine views"><a href="#doctrine" ${mode==='course'?'aria-current="page"':''}>Catechism course <small>107</small></a><a href="#doctrine/topics" ${mode==='names'?'aria-current="page"':''}>Doctrine index <small>33</small></a><a href="#doctrine/studies" ${mode==='studies'?'aria-current="page"':''}>Passage studies <small>132</small></a></nav>`}
function renderCourseIndex(){const next=DATA.catechismCourse.find(l=>!prefs.doctrineRead.includes(l.id))||DATA.catechismCourse[0];return pageTop('Doctrine through the Shorter Catechism','Learn the faith.','All 107 Shorter Catechism questions, with biblical explanations and further study in the Westminster Standards.')+`<div class="wrap browse-shell">${doctrineViewLinks('course')}<div class="course-start"><div><span class="eyebrow">${courseFinished()?'Your course':'A place to begin'}</span><h2>${courseFinished()?`${courseFinished()} of 107 lessons read`:'What are we made for?'}</h2><p>${courseFinished()?'Continue with the next unread lesson, or choose a subject below.':'Begin with our chief end, then follow the Catechism through what we believe and how we live.'}</p></div><a class="button small" href="#doctrine/course/${next.id}">${courseFinished()?'Continue':'Begin lesson 1'} →</a></div><div class="browse-filters"><label class="field grow">Find a lesson<input type="search" id="catechismQuery" value="${esc(courseBrowse.q)}" placeholder="Faith, the commandments, prayer…"></label><label class="field">Course section<select id="catechismUnit">${['All',...DATA.courseUnits.map(g=>g.title)].map(t=>`<option ${courseBrowse.unit===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><button class="button secondary small" data-course-reset>Reset</button></div><div id="catechismResults" tabindex="-1">${courseResults()}</div><div class="quiet-links"><a href="#doctrine/further">Nine further lessons →</a><a href="#doctrine/coverage">How the course connects to the Standards →</a></div><p class="small muted">The source answers are preserved as published at thewestminsterstandard.org. Explanations are editorial and subordinate to Scripture. Marking a lesson read records study, not mastery.</p></div>`}
function wcfLinks(l){return l.wcf.split(';').map(r=>confessionLinks('WCF '+r)).join(' · ')}
function sourceDisclosure(doc,section,unit,title){const d=standardsMap[doc],s=d.sections[section-1],u=unit?s.units.find(x=>x.number===unit):s.units[0];return `<details class="source-study"><summary>${esc(title)}${u.question?`<span>${esc(u.question)}</span>`:''}</summary><div class="source-study-body"><div class="standard-wording">${u.html}</div>${u.proofHtml?`<details class="standard-proofs"><summary>Scripture proofs in the source</summary><div>${u.proofHtml}</div></details>`:''}<p class="small"><a href="#standards/${doc}/${section}${unit?'/'+unit:''}">Open in the Standards reader →</a></p></div></details>`}
function courseSources(l){return `<section class="course-section" id="course-deeper"><h2>Go deeper in the Standards</h2><p class="small muted">Open the source wording when you’re ready to examine the distinction more closely. These historical answers are source text, not additional editorial explanations.</p><h3>Larger Catechism</h3>${l.wlc.map(n=>sourceDisclosure('wlc',n,null,'WLC '+n)).join('')}<h3>Confession of Faith</h3>${l.wcf.split(';').map(r=>{const [c,p]=r.split('.').map(Number);return sourceDisclosure('wcf',c,p,'WCF '+r)}).join('')}<p class="small"><a href="${esc(standardsMap.wsc.source)}" target="_blank" rel="noopener noreferrer">Shorter Catechism source ↗</a> · <a href="${esc(standardsMap.wlc.source)}" target="_blank" rel="noopener noreferrer">Larger Catechism source ↗</a> · <a href="${esc(standardsMap.wcf.source)}" target="_blank" rel="noopener noreferrer">Confession source ↗</a></p></section>`}
function courseTools(){return `<div class="course-reader-tools"><div class="font-control"><button class="icon" data-size="-1" aria-label="Decrease reading text size">A−</button><output class="size-output">${prefs.size}px</output><button class="icon" data-size="1" aria-label="Increase reading text size">A+</button></div><nav aria-label="In this lesson"><a href="#" data-course-scroll="course-teaching">Explanation</a><a href="#" data-course-scroll="course-exercise">Check understanding</a><a href="#" data-course-scroll="course-deeper">Go deeper</a></nav></div>`}
function courseCompletion(l,extra=false){const id=extra?'further-'+l.id:l.id,done=prefs.doctrineRead.includes(id);return `<div class="course-completion"><button class="button secondary small" data-doctrine-done="${id}" aria-pressed="${done}">${done?'✓ Lesson marked read':'Mark lesson read'}</button><a href="#doctrine">All catechism lessons →</a></div>`}
function renderCatechismLesson(id){const l=catechismMap[id];if(!l)return pageTop('Doctrine course','That lesson could not be found.')+'<div class="wrap"><a href="#doctrine">Return to the course</a></div>';const g=courseUnit(l),u=standardsMap.wsc.sections[l.number-1].units[0],words=[u.text,l.teach,l.argument,l.guard,l.answer].join(' ').split(/\s+/).length;return `<div class="wrap"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#doctrine">Catechism course</a><span>/</span><span>${esc(g.title)}</span></nav><header class="reader-head"><span class="eyebrow">Lesson ${l.number} of 107 · About ${Math.max(3,Math.ceil(words/150))} minutes before further study</span><h1 class="lesson-title">${esc(l.title)}</h1></header>${courseTools()}<label class="field course-lesson-jump">Another lesson<select id="catechismLesson">${DATA.catechismCourse.map(x=>`<option value="${x.id}" ${x===l?'selected':''}>${x.number}. ${esc(x.title)}</option>`).join('')}</select></label><div class="reader-layout"><aside class="reader-sidebar course-sidebar"><span class="sidebar-title">${esc(g.title)}</span><nav aria-label="Lessons in this course section">${DATA.catechismCourse.filter(x=>courseUnit(x)===g).map(x=>`<a href="#doctrine/course/${x.id}" ${x===l?'aria-current="page"':''}>${x.number}. ${esc(x.title)}${prefs.doctrineRead.includes(x.id)?' ✓':''}</a>`).join('')}</nav><div class="sidebar-foot"><a href="#doctrine/coverage">Connections to the Standards →</a></div></aside><article class="reader prose catechism-reader"><section class="catechism-answer"><span class="eyebrow">Shorter Catechism · Source wording</span><h2>Q. ${l.number}. ${esc(u.question)}</h2><div class="standard-wording">${u.html}</div>${u.proofHtml?`<details class="standard-proofs"><summary>Scripture proofs in the source</summary><div>${u.proofHtml}</div></details>`:''}<p class="small"><a href="#standards/wsc/${l.number}">Read the source answer →</a></p></section><section class="course-section" id="course-teaching"><span class="eyebrow">Editorial explanation</span><h2>Understanding the doctrine</h2><p>${esc(l.teach)}</p></section><section class="course-section"><h2>Work through the passage</h2><button class="button secondary small" data-bible="${esc(l.ref)}">Read ${esc(l.ref)} · KJV</button><p>${esc(l.argument)}</p><p class="small muted">Read the surrounding chapter before drawing the doctrinal conclusion. The passage's actual words govern the explanation.</p></section><section class="course-section"><h2>A distinction to keep</h2><p>${esc(l.guard)}</p></section><section class="lesson-exercise course-section" id="course-exercise"><h2>Check your understanding</h2><p>${esc(l.exercise)}</p><details class="check-answer"><summary>Compare your reasoning</summary><div><p>${esc(l.answer)}</p></div></details></section>${courseCompletion(l)}${courseSources(l)}<nav class="guide-nav" aria-label="Adjacent catechism lessons">${l.number>1?`<a class="button secondary" href="#doctrine/course/${l.number-1}">← Lesson ${l.number-1}</a>`:'<a class="button secondary" href="#doctrine">All lessons</a>'}${l.number<107?`<a class="button" href="#doctrine/course/${l.number+1}">Lesson ${l.number+1} →</a>`:'<a class="button" href="#doctrine/further">Further lessons →</a>'}</nav></article></div></div>`}
function renderSupplements(id){const l=supplementMap[id];if(!l)return pageTop('Continue your doctrinal study','Nine further lessons.','Subjects that need fuller treatment alongside the Shorter Catechism course.')+`<div class="wrap browse-shell"><div class="browse-rows">${DATA.doctrineSupplements.map(x=>`<a class="browse-row" href="#doctrine/further/${x.id}"><span><strong>${esc(x.title)}</strong><small>${prefs.doctrineRead.includes('further-'+x.id)?'✓ Read · ':''}${esc(x.ref)}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div><div class="quiet-links"><a href="#doctrine">Catechism course →</a><a href="#doctrine/coverage">Connections to the Standards →</a></div></div>`;return `<div class="wrap"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#doctrine">Doctrine course</a><span>/</span><a href="#doctrine/further">Further lessons</a></nav><header class="reader-head"><span class="eyebrow">Further study · Editorial explanation</span><h1 class="lesson-title">${esc(l.title)}</h1></header>${courseTools()}<article class="reader prose catechism-reader supplement-reader"><section class="course-section" id="course-teaching"><h2>Understanding the doctrine</h2>${l.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<button class="button secondary small" data-bible="${esc(l.ref)}">Read ${esc(l.ref)} · KJV</button></section><section class="lesson-exercise course-section" id="course-exercise"><h2>Check your understanding</h2><p>${esc(l.exercise)}</p><details class="check-answer"><summary>Compare your reasoning</summary><div><p>${esc(l.answer)}</p></div></details></section>${courseCompletion(l,true)}${courseSources(l)}<nav class="guide-nav"><a class="button secondary" href="#doctrine/further">← Further lessons</a><a class="button" href="#doctrine">Catechism course →</a></nav></article></div>`}
function renderCoverage(){return pageTop('A map for further study','Follow the teaching through the Standards.','The course covers every Shorter Catechism question. These connections help you compare its teaching with all 33 Confession chapters and all 196 Larger Catechism questions.')+`<div class="wrap browse-shell"><p class="small muted">A reference map shows where material is addressed. It doesn't claim that an editorial lesson exhausts a doctrine or replaces reading the source. Open a chapter when you want its fuller confession.</p><details class="browse-group"><summary><span><strong>The 33 Confession chapters</strong></span><span class="group-count">All chapters linked</span></summary><div>${DATA.confessionCoverage.map(c=>`<details class="coverage-item"><summary>${c.number}. ${esc(c.title)}</summary><p class="small"><a href="#standards/wcf/${c.number}">Read the complete chapter →</a></p><ul>${c.lessons.map(l=>`<li><a href="#${l.route}">${esc(l.title)}</a></li>`).join('')}</ul></details>`).join('')}</div></details><details class="browse-group"><summary><span><strong>The 196 Larger Catechism questions</strong></span><span class="group-count">All questions linked</span></summary><div>${standardsMap.wlc.sections.map(s=>{const links=[...DATA.catechismCourse,...DATA.doctrineSupplements].filter(l=>l.wlc.includes(s.number));return `<details class="coverage-item"><summary>WLC ${s.number}. ${esc(s.units[0].question)}</summary><p class="small"><a href="#standards/wlc/${s.number}">Read the source answer →</a></p><ul>${links.map(l=>`<li><a href="#doctrine/${l.number?'course/':'further/'}${l.id}">${esc(l.title)}</a></li>`).join('')}</ul></details>`}).join('')}</div></details><div class="quiet-links"><a href="#doctrine">Return to the course →</a><a href="#standards">Read the complete Standards →</a></div></div>`}
const compactDoctrineIndex=renderDoctrine;
renderDoctrine=function(id){const [,s,n]=path();if(!id)return renderCourseIndex();if(id==='course')return renderCatechismLesson(n);if(id==='further')return renderSupplements(n);if(id==='coverage')return renderCoverage();let content=compactDoctrineIndex(id==='topics'?undefined:id);const mode=id==='studies'?'studies':'names';content=content.replace(/<nav class="view-switch"[\s\S]*?<\/nav>/,doctrineViewLinks(mode));if(DATA.doctrines.some(p=>p.id===id)){const p=DATA.doctrines.find(p=>p.id===id);const chapters=new Set((p.confession.match(/WCF\s+\d+/g)||[]).map(r=>Number(r.match(/\d+/)[0])));const related=DATA.catechismCourse.filter(l=>l.wcf.split(';').some(r=>chapters.has(+r.split('.')[0]))).slice(0,5);content=content.replace('<h2>What the doctrine teaches</h2>',`<div class="doctrine-course-link"><strong>Work through the doctrine in more depth</strong><ul>${related.map(l=>`<li><a href="#doctrine/course/${l.id}">Lesson ${l.number}. ${esc(l.title)}</a></li>`).join('')}</ul><a href="#doctrine">Browse the full catechism course →</a></div><h2>What the doctrine teaches</h2>`)}return content};
const beforeCourseRender=render;
render=function(){beforeCourseRender();const [p,s,n]=path();if(p==='doctrine'){document.title=(s==='course'&&catechismMap[n]?catechismMap[n].title:s==='further'&&supplementMap[n]?supplementMap[n].title:s==='coverage'?'Connections to the Standards':s==='topics'?'Doctrine index':'Doctrine course')+' | Bible Reading Helps'}};
DATA.catechismCourse.forEach(l=>searchIndex.push({title:'WSC '+l.number+' · '+l.title,kind:'Doctrine course lesson',route:'doctrine/course/'+l.id,body:[l.teach,l.argument,l.guard,l.exercise,l.answer,...l.wlc.map(n=>'WLC '+n)].join(' ')}));
