 const labelled=/\b(?:verses?|ver\.)\s+(\d{1,3}(?:\s*[-–—]\s*\d{1,3})?(?:\s*[,\.]\s*\d{1,3}(?:\s*[-–—]\s*\d{1,3})?)*)/gi;
 for(const m of s.matchAll(labelled)){const start=m.index+m[0].indexOf(m[1]);const prev=matches.filter(x=>x.end<=start).sort((a,b)=>a.start-b.start).at(-1),book=prev?BIBLE[prev.parsed.bi].name:state.book||context.defaultBook,ch=prev?prev.parsed.segments.at(-1).ch:state.ch||context.defaultChapter;if(!book||!ch)continue;const parsed=parseRef(book+' '+ch+':'+m[1].replace(/\./g,','),context.source);if(parsed){matches.push({start,end:start+m[1].length,label:m[1],ref:parsed.canonical,parsed,explicit:false});occupied.push([start,start+m[1].length])}}
 const bareRE=/\b(?:\d{1,3}|[ivxlcdm]+)\s*[.:]\s*\d{1,3}(?:\s*(?:[-–—]|\bto\b)\s*(?:\d{1,3}\s*[.:]\s*)?\d{1,3})?(?:\s*,\s*\d{1,3}(?![\d]|\s*[.:])(?:\s*[-–—]\s*\d{1,3})?)*/gi;
 for(const m of s.matchAll(bareRE)){if(occupied.some(([a,z])=>m.index>=a&&m.index<z))continue;const before=s.slice(0,m.index);if(/\b(?:WCF|WLC|WSC)\s*$/i.test(before)||/\d\.$/.test(before))continue;const prev=matches.filter(x=>x.end<=m.index).sort((a,b)=>a.start-b.start).at(-1);const join=prev?s.slice(prev.end,m.index):'';const connected=prev&&/^[\s,;()]*(?:(?:and|or|with|compare|cf\.?)[\s,;()]*)*$/i.test(join);let book=connected?BIBLE[prev.parsed.bi].name:context.defaultBook;if(context.proof)book=prev?BIBLE[prev.parsed.bi].name:state.book||context.defaultBook;if(!book)continue;const parsed=parseRef(book+' '+m[0],context.source);if(!parsed)continue;const chapterLabel=before.match(/\bchapters?\s*$/i),start=chapterLabel&&!context.source?m.index-chapterLabel[0].length:m.index;matches.push({start,end:m.index+m[0].length,label:m[0],ref:parsed.canonical,parsed,explicit:false});occupied.push([start,m.index+m[0].length])}
