 for(const m of s.matchAll(shortRE)){const offset=m.index+m[0].indexOf(m[1]),end=offset+m[1].length;if(occupied.some(([a,z])=>offset>=a&&offset<z))continue;if(!context.proof&&!/^\s*(?:verses?|ver\.)/i.test(m[0]))continue;const prev=matches.filter(x=>x.end<=offset).sort((a,b)=>a.start-b.start).at(-1),book=prev?BIBLE[prev.parsed.bi].name:state.book,ch=prev?prev.parsed.segments.at(-1).ch:state.ch;if(!book||!ch)continue;const parsed=parseRef(book+' '+ch+':'+m[1],context.source);if(!parsed)continue;matches.push({start:offset,end,label:m[1],ref:parsed.canonical,parsed,explicit:false});occupied.push([offset,end])}
 const chapters=/\bchapters?\s+(\d{1,3}(?:\s*(?:[-–—]|to)\s*\d{1,3})?)(?![\d.:])/gi;
 if(context.defaultBook)for(const m of s.matchAll(chapters)){const start=m.index,end=m.index+m[0].length;if(occupied.some(([a,z])=>m.index+m[0].indexOf(m[1])>=a&&m.index+m[0].indexOf(m[1])<z))continue;const parsed=parseRef(context.defaultBook+' '+m[1]);if(parsed){matches.push({start,end,label:m[1],ref:parsed.canonical,parsed,explicit:false});occupied.push([start,end])}}
 if(context.leadingVerse){const m=s.match(/^\s*(\d+)\b/);if(m&&!occupied.some(([a,z])=>m.index>=a&&m.index<z)){const start=s.indexOf(m[1]),parsed=parseRef(context.defaultBook+' '+context.defaultChapter+':'+m[1]);if(parsed)matches.push({start,end:start+m[1].length,label:m[1],ref:parsed.canonical,parsed,explicit:false})}}
