extractRefs=function(t){return scriptureMatches(String(t),{}).matches.map(m=>m.ref)};
drawBible=function(){const s=bibleState,b=BIBLE[s.bi],chapter=b.chapters[s.ch-1],segments=s.segments||((s.vs||s.extra)?[{ch:s.ch,vs:s.vs,ve:s.ve||s.vs},...(s.extra?[{ch:s.ch,vs:s.extra,ve:s.extra}]:[])]:[]),active=segments.filter(r=>r.ch===s.ch);$('#bibleBook').value=s.bi;$('#bibleChapter').innerHTML=b.chapters.map((_,i)=>`<option value="${i+1}" ${i+1===s.ch?'selected':''}>${i+1}</option>`).join('');$('#bibleTitle').textContent=b.name+' '+s.ch;const multi=new Set(segments.map(r=>r.ch)).size>1;$('#bibleNote').textContent=s.warning||((multi?'Requested passage '+s.canonical+'. Use Next or the chapter selector to read the remaining chapters. ':'')+(active.some(r=>r.vs)?'The requested verses are highlighted. The whole chapter is shown for context.':'The whole chapter is shown.'));$('#bibleText').innerHTML=chapter.map((v,i)=>`<p class="verse-line ${active.some(r=>r.vs?i+1>=r.vs&&i+1<=r.ve:multi)?'highlight':''}" id="verse-${i+1}"><sup>${i+1}</sup>${esc(v)}</p>`).join('');$('#biblePrev').disabled=s.bi===0&&s.ch===1;$('#bibleNext').disabled=s.bi===65&&s.ch===BIBLE[65].chapters.length;const target=active.find(r=>r.vs);if(target)setTimeout(()=>$('#verse-'+target.vs)?.scrollIntoView({block:'center',behavior:'instant'}),0);else $('#bibleDialog').scrollTop=0};
